427	  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
428	
429	  /* ---------- Ticker ---------- */
430	  document.getElementById('ticker').innerHTML = Array(24).fill('<span>BLAZE</span><span class="sep" aria-hidden="true"></span>').join('');
431	
432	  /* ---------- Wordmark: fit to the full width ---------- */
433	  const wrap = document.getElementById('wordmarkWrap');
434	  const mark = document.getElementById('wordmark');
435	  function fitWordmark() {
436	    if (!wrap.clientWidth) return;
437	    mark.style.fontSize = '200px';
438	    mark.style.fontSize = (200 * (wrap.clientWidth - 40) / mark.offsetWidth) + 'px';
439	  }
440	  let resizeTimer;
441	  window.addEventListener('resize', () => { clearTimeout(resizeTimer); resizeTimer = setTimeout(fitWordmark, 150); });
442	  (document.fonts ? document.fonts.ready : Promise.resolve()).then(fitWordmark);
443	  fitWordmark();
444	
445	  /* ---------- The story: three parts, one at a time ---------- */
446	  const part = (n) => document.querySelector(`[data-part="${n}"]`);
447	  const startBtn = document.getElementById('startBtn'), byline = document.getElementById('byline');
448	  const skipBtn = document.getElementById('skip');
449	  let timers = [];
450	  const at = (ms, fn) => timers.push(setTimeout(fn, ms));
451	  const show = (n) => { part(n).classList.remove('out'); part(n).classList.add('in'); };
452	  const hide = (n) => part(n).classList.replace('in', 'out');
453	
454	  function finish() {
455	    timers.forEach(clearTimeout); timers = [];
456	    [1, 2].forEach((n) => part(n).classList.remove('in', 'out'));
457	    show(3); startBtn.classList.add('in'); byline.classList.add('in'); skipBtn.hidden = true;
458	  }
459	  function play() {
460	    fitWordmark();
461	    timers.forEach(clearTimeout); timers = [];
462	    document.querySelectorAll('.part, #startBtn, #byline').forEach((el) => el.classList.remove('in', 'out'));
463	    skipBtn.hidden = false;
464	    if (reduceMotion) return finish();
465	    at(300,   () => show(1));
466	    at(3600,  () => hide(1));
467	    at(4500,  () => show(2));
468	    at(7800,  () => hide(2));
469	    at(8700,  () => show(3));
470	    at(10000, () => startBtn.classList.add('in'));
471	    at(10600, () => { byline.classList.add('in'); skipBtn.hidden = true; });
472	  }
473	  skipBtn.addEventListener('click', finish);
474	
475	  // Replays every time the start screen is opened
476	  window.BlazeIntro = { play, stop: () => { timers.forEach(clearTimeout); timers = []; } };
477	})();
