546	  /* ---------- Word diff (LCS) ---------- */
547	  function diffWords(a, b) {
548	    const A = a.split(/\s+/).filter(Boolean), B = b.split(/\s+/).filter(Boolean);
549	    const n = A.length, m = B.length;
550	    const dp = Array.from({ length: n + 1 }, () => new Uint16Array(m + 1));
551	    for (let i = n - 1; i >= 0; i--)
552	      for (let j = m - 1; j >= 0; j--)
553	        dp[i][j] = A[i] === B[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
554	
555	    const ops = [];
556	    const push = (t, w) => { const last = ops[ops.length - 1]; if (last && last.t === t) last.w.push(w); else ops.push({ t, w: [w] }); };
557	    let i = 0, j = 0;
558	    while (i < n && j < m) {
559	      if (A[i] === B[j]) { push('eq', A[i]); i++; j++; }
560	      else if (dp[i + 1][j] >= dp[i][j + 1]) push('del', A[i++]);
561	      else push('ins', B[j++]);
562	    }
563	    while (i < n) push('del', A[i++]);
564	    while (j < m) push('ins', B[j++]);
