566	    // Group adjacent deletions/insertions into one change ("hunk")
567	    let segs = [], h = null;
568	    for (const op of ops) {
569	      if (op.t === 'eq') { h = null; segs.push({ eq: op.w }); }
570	      else { if (!h) { h = { del: [], ins: [] }; segs.push({ hunk: h }); } h[op.t].push(...op.w); }
571	    }
572	    // Merge two changes separated by a single unchanged word: easier to read
573	    for (let k = 1; k < segs.length - 1; k++) {
574	      const a1 = segs[k - 1], mid = segs[k], b1 = segs[k + 1];
575	      if (a1.hunk && mid.eq && mid.eq.length === 1 && b1.hunk) {
576	        a1.hunk.del.push(mid.eq[0], ...b1.hunk.del);
577	        a1.hunk.ins.push(mid.eq[0], ...b1.hunk.ins);
578	        segs.splice(k, 2); k--;
579	      }
580	    }
581	    return segs.map((s) => s.hunk ? { hunk: { del: s.hunk.del.join(' '), ins: s.hunk.ins.join(' ') } } : { eq: s.eq.join(' ') });
582	  }
583	
584	  function applyDecisions(segs, dec) {
585	    let hi = 0;
586	    return segs.map((s) => {
587	      if (s.eq != null) return s.eq;
588	      return dec[hi++] === 'keep' ? s.hunk.ins : s.hunk.del;
589	    }).filter(Boolean).join(' ');
590	  }
591	
592	  /* ---------- State ---------- */
593	  const S = { mode: 'empty', pid: null, iters: [], cur: 0, segs: [], dec: [], timer: null, queue: [], queued: false, undo: [] };
594	  const hunkCount = () => S.segs.filter((s) => s.hunk).length;
595	  const pending = () => S.dec.filter((d) => d == null).length;
596	
597	  const panel = $('#panel'), hint = $('#hint'), pill = $('#pill'), pop = $('#pop');
598	  const palette = $('#palette'), paletteList = $('#paletteList');
599	  let lastPid = 'why', openHunk = null;
600	
601	  function setActive(pid, cls) {
602	    document.querySelectorAll('[data-pid]').forEach((el) => el.classList.remove('active', 'thinking'));
603	    if (pid) paraEl(pid).classList.add(...cls);
604	  }
605	
606	  /* ---------- Asking for a suggestion ---------- */
607	  function ask(pid, key, custom) {
608	    hidePill(); hidePop();
609	    if (!PARAS[pid]) { toast('In this prototype, try “Why now”, “How we’ll keep it safe” or “Success metrics”.'); return; }
610	    const refining = (S.mode === 'review' || S.mode === 'thinking') && S.pid === pid;
611	    if (S.mode !== 'empty' && !refining) { renderPlain(S.pid); toast('Previous suggestion discarded'); }
612	    if (!refining) S.iters = [];
613	    clearTimeout(S.timer);
614	    if (!S.queued && pid !== 'metrics') { S.queue = ['metrics']; S.queued = true; }
615	
616	    const v = PARAS[pid].v[key] || PARAS[pid].v.rewrite;
617	    const label = custom ? `“${custom}”` : ACTIONS[key].label;
618	    const why = custom ? `You asked: <em>${esc(custom)}</em>. ${v[1]}` : esc(v[1]);
619	
620	    lastPid = pid;
621	    S.pid = pid; S.mode = 'thinking'; S.thinkingLabel = label;
622	    hint.classList.add('gone');
623	    setActive(pid, ['active', 'thinking']);
624	    renderPanel();
625	    const r = paraEl(pid).getBoundingClientRect(), phone = innerWidth <= 820;
626	    if (phone) paraEl(pid).scrollIntoView({ block: 'start', behavior: 'smooth' });
627	    else if (r.top < 0 || r.bottom > innerHeight) paraEl(pid).scrollIntoView({ block: 'center', behavior: 'smooth' });
628	    S.timer = setTimeout(() => {
629	      S.iters.push({ key, label, text: v[0], why });
630	      showIteration(S.iters.length - 1);
631	    }, 900 + Math.random() * 600);
632	  }
633	
634	  function cancelThinking() {
635	    clearTimeout(S.timer);
636	    if (S.iters.length) showIteration(S.cur);
637	    else { S.mode = 'empty'; renderPlain(S.pid); setActive(null); renderPanel(); }
638	  }
639	
640	  function showIteration(i) {
641	    S.cur = i; S.mode = 'review';
642	    S.segs = diffWords(current[S.pid], S.iters[i].text);
643	    S.dec = Array(hunkCount()).fill(null);
644	    setActive(S.pid, ['active']);
645	    renderDiff(); renderPanel();
646	  }
647	
648	  /* ---------- Inline diff ---------- */
649	  function renderDiff() {
650	    let hi = 0;
651	    paraEl(S.pid).innerHTML = S.segs.map((s) => {
652	      if (s.eq != null) return esc(s.eq);
653	      const i = hi++, d = S.dec[i], { del, ins } = s.hunk;
654	      if (d === 'keep') return `<span class="hunk kept" data-h="${i}">${ins ? `<ins>${esc(ins)}</ins>` : '<span class="mark"></span>'}</span>`;
655	      if (d === 'drop') return `<span class="hunk dropped" data-h="${i}">${del ? esc(del) : '<span class="mark"></span>'}</span>`;
656	      return `<span class="hunk" data-h="${i}" title="Click to keep or discard">${del ? `<del>${esc(del)}</del>` : ''}${del && ins ? ' ' : ''}${ins ? `<ins>${esc(ins)}</ins>` : ''}</span>`;
657	    }).join(' ');
658	  }
659	
660	  $('#sheet').addEventListener('click', (e) => {
661	    const h = e.target.closest('.hunk');
662	    if (!h || S.mode !== 'review') return;
663	    e.stopPropagation();
664	    hidePill();
665	    document.querySelectorAll('.hunk.open').forEach((x) => x.classList.remove('open'));
666	    h.classList.add('open');
667	    openHunk = +h.dataset.h;
668	    const r = h.getBoundingClientRect();
669	    pop.hidden = false;
670	    pop.style.left = Math.max(8, Math.min(r.left, innerWidth - pop.offsetWidth - 8)) + 'px';
671	    pop.style.top = (r.bottom + 8) + 'px';
672	  });
673	  pop.addEventListener('click', (e) => {
674	    const b = e.target.closest('[data-pop]');
675	    if (!b || openHunk == null) return;
676	    S.dec[openHunk] = b.dataset.pop;
677	    hidePop(); renderDiff(); renderPanel();
678	  });
679	  function hidePop() { pop.hidden = true; openHunk = null; document.querySelectorAll('.hunk.open').forEach((x) => x.classList.remove('open')); }
680	
681	  /* ---------- Accept / reject: one transaction ---------- */
682	  function apply(dec) {
683	    const kept = dec.filter((d) => d === 'keep').length;
684	    const pid = S.pid;
685	    S.undo.push({ pid, text: current[pid] });
686	    current[pid] = applyDecisions(S.segs, dec);
687	    finish(pid);
688	    toast(`Applied ${kept} change${kept === 1 ? '' : 's'}`, true);
689	  }
690	  function acceptAll() { if (S.mode === 'review') apply(S.dec.map(() => 'keep')); }
691	  function applyDecided() { if (S.mode === 'review') apply(S.dec.map((d) => d || 'drop')); }
692	  function rejectAll() { if (S.mode !== 'review') return; const pid = S.pid; finish(pid); toast('Suggestion rejected — your text is unchanged'); }
693	  function finish(pid) {
694	    S.mode = 'empty'; S.iters = [];
695	    if (pid === 'metrics') S.queue = [];
696	    renderPlain(pid); setActive(null); hidePop(); renderPanel();
697	  }
698	  function undo() {
699	    const last = S.undo.pop();
700	    if (!last) return;
701	    if (S.mode !== 'empty' && S.pid === last.pid) { clearTimeout(S.timer); S.mode = 'empty'; setActive(null); }
702	    current[last.pid] = last.text;
703	    renderPlain(last.pid); renderPanel();
704	    toast('Undone');
705	  }
706	
707	  /* ---------- Co-author panel ---------- */
708	  const pad = (n) => String(n).padStart(2, '0');
709	  const dot = () => `<span class="dot"></span>`;
710	  const kbd = (s) => `<span class="kbd">${s}</span>`;
711	  const mod = isMac ? '⌘' : 'Ctrl';
712	
713	  function nextCard(disabled) {
714	    if (!S.queue.length || (S.mode !== 'empty' && S.pid === 'metrics')) return '';
715	    return `<div class="next"><div><span class="lbl">Up next</span><b>Success metrics</b> · Make the goal measurable</div>
716	      <button type="button" data-act="next" ${disabled ? 'disabled' : ''}>${disabled ? 'After this one' : 'Review'}</button></div>`;
717	  }
718	
719	  function handle() {
720	    const txt = S.mode === 'empty' ? 'Co-author · nothing to review'
721	      : S.mode === 'thinking' ? 'Thinking…'
722	      : `${pending()} change${pending() === 1 ? '' : 's'} to review`;
723	    return `<button class="sheet-handle" type="button" data-act="sheet"><span>${txt}</span><span class="chev">▴</span></button>`;
724	  }
725	  function renderPanel() {
726	    if (S.mode !== S.lastMode) { panel.classList.toggle('expanded', S.mode !== 'empty'); S.lastMode = S.mode; }
727	    panel.innerHTML = handle() + panelBody();
728	    document.documentElement.style.setProperty('--sheet-h', panel.offsetHeight + 'px');
729	  }
730	  function panelBody() {
731	    if (S.mode === 'empty') {
732	      return `
733	        ${nextCard(false)}
734	        <div class="card">
735	          <p class="lbl">03 · Co-author</p>
736	          <div class="num">00</div>
737	          <p class="ttl">Nothing to review yet</p>
738	          <p class="sub">Select text in the document and pick an action, or press ${kbd('/')}. Suggestions appear inline as a diff, and nothing changes until you accept.</p>
739	          <div class="sep"></div>
740	          <p class="lbl">Try one</p>
741	          <div class="tries">
742	            <button class="try" type="button" data-try="why:shorter">${dot('shorter')}Make “Why now” shorter</button>
743	            <button class="try" type="button" data-try="metrics:measurable">${dot('measurable')}Make the success metric measurable</button>
744	            <button class="try" type="button" data-try="safe:formal">${dot('formal')}Make the safety section more formal</button>
745	          </div>
746	        </div>
747	        <div class="keys"><p class="lbl">Shortcuts</p><dl>
748	          <dt>${kbd('/')}</dt><dd>Command palette</dd>
749	          <dt>${kbd(mod + ' ↵')}</dt><dd>Accept all</dd>
750	          <dt>${kbd('Esc')}</dt><dd>Reject all</dd>
751	          <dt>${kbd(mod + ' Z')}</dt><dd>Undo</dd></dl></div>
752	        <p class="proto mono">Prototype · suggestions are pre-written</p>`;
753	    }
754	
755	    const title = PARAS[S.pid].title;
756	    if (S.mode === 'thinking') {
757	      return `
758	        <div class="card">
759	          <p class="lbl">03 · ${esc(title)}</p>
760	          <p class="think">Thinking<span class="dots"></span></p>
761	          <p class="sub">${S.thinkingLabel} — only this paragraph, nothing else in the document.</p>
762	          <div class="acts" style="grid-template-columns:auto"><button class="b b--ghost" type="button" data-act="cancel">Cancel</button></div>
763	        </div>${nextCard(true)}`;
764	    }
765	
766	    // review
767	    const it = S.iters[S.cur], total = hunkCount(), left = pending();
768	    const decided = total - left, kept = S.dec.filter((d) => d === 'keep').length;
769	    const hist = S.iters.map((x, i) => `<button type="button" class="${i === S.cur ? 'on' : ''}" data-iter="${i}">${x.label}</button>`).join('<span>→</span>');
770	    const chips = ['formal', 'warmer', 'keep', 'shorter', ...(S.pid === 'metrics' ? ['measurable'] : [])]
771	      .filter((k) => k !== it.key)
772	      .map((k) => `<button class="chip" type="button" data-refine="${k}">${dot(k)}${ACTIONS[k].label}</button>`).join('');
773	
774	    return `
775	      <div class="card">
776	        <p class="lbl">03 · Suggestion · ${esc(title)}</p>
777	        ${total === 0 ? `<p class="ttl" style="margin-top:14px">No changes suggested</p><p class="sub">This already reads well for “${it.label}”.</p>` : `
778	        <div class="numrow"><div class="num">${pad(left)}</div><p>${left === 1 ? 'change' : 'changes'} left<br>to review · ${total} total</p></div>`}
779	        <div class="hist">${hist}</div>
780	        <p class="why">${it.why}</p>
781	        <div class="acts">
782	          <button class="b b--primary" type="button" data-act="accept" ${total ? '' : 'disabled'}>Accept all ${kbd(mod + '↵')}</button>
783	          <button class="b b--ghost" type="button" data-act="reject">${total ? 'Reject all' : 'Close'} ${kbd('Esc')}</button>
784	        </div>
785	        ${decided ? `<button class="b b--apply" type="button" data-act="apply">Apply · ${kept} kept, ${total - kept} dropped</button>` : ''}
786	        <div class="sep"></div>
787	        <p class="lbl">Refine this suggestion</p>
788	        <div class="chips">${chips}</div>
789	        <form class="refine" id="refineForm"><input name="q" autocomplete="off" placeholder="Or tell Blaze what to change…"><button type="submit" aria-label="Send">↵</button></form>
790	      </div>
791	      ${nextCard(true)}
792	      <p class="tip">Click any change in the text to keep or discard it.</p>`;
793	  }
794	
795	  panel.addEventListener('click', (e) => {
796	    const t = e.target.closest('button');
797	    if (!t) return;
798	    if (t.dataset.try) { const [pid, key] = t.dataset.try.split(':'); ask(pid, key); }
799	    else if (t.dataset.refine) ask(S.pid, t.dataset.refine);
800	    else if (t.dataset.iter) showIteration(+t.dataset.iter);
801	    else if (t.dataset.act === 'accept') acceptAll();
802	    else if (t.dataset.act === 'reject') rejectAll();
803	    else if (t.dataset.act === 'apply') applyDecided();
804	    else if (t.dataset.act === 'cancel') cancelThinking();
805	    else if (t.dataset.act === 'next') ask('metrics', 'measurable');
806	    else if (t.dataset.act === 'sheet') { panel.classList.toggle('expanded'); document.documentElement.style.setProperty('--sheet-h', panel.offsetHeight + 'px'); }
807	  });
808	  panel.addEventListener('submit', (e) => {
809	    e.preventDefault();
810	    const q = e.target.q.value.trim();
811	    if (q) ask(S.pid, keyFor(q, S.pid), q);
812	  });
