541	  const current = Object.fromEntries(Object.entries(PARAS).map(([k, p]) => [k, p.text]));
542	  const paraEl = (pid) => document.querySelector(`[data-pid="${pid}"]`);
543	  const renderPlain = (pid) => { paraEl(pid).textContent = current[pid]; };
544	  Object.keys(PARAS).forEach(renderPlain);
