  function keyFor(q, pid) {
    q = q.toLowerCase();
    if (/short|concise|brief|cut/.test(q)) return 'shorter';
    if (/formal|professional/.test(q)) return 'formal';
    if (/warm|friendly|human|kind/.test(q)) return 'warmer';
    if (/grammar|typo|spell|punctuat/.test(q)) return 'grammar';
    if (/measur|metric|number|target|specific/.test(q) && PARAS[pid].v.measurable) return 'measurable';
    if (/wording|minimal|light/.test(q)) return 'keep';
    return 'rewrite';
  }

  /* ---------- Floating pill over the selection ---------- */
  function pidFromNode(n) {
    const el = (n && n.nodeType === 3 ? n.parentElement : n);
    const p = el && el.closest('[data-pid]');
    return p ? p.dataset.pid : (el && el.closest('#sheet') ? 'other' : null);
  }
  let pillPid = null;

  let pillRect = null;
  function showPill(rect, pid) {
    pillPid = pid; pillRect = rect;
    pill.innerHTML = `
      <button type="button" data-pill="ask">✦ Ask</button><span class="pill__sep"></span>
      <button type="button" data-pill="rewrite">${dot('rewrite')}Rewrite</button>
      <button type="button" data-pill="shorter">${dot('shorter')}Shorter</button>
      <button type="button" data-pill="tone">${dot('formal')}Tone ▾</button>
      <button type="button" data-pill="grammar">${dot('grammar')}Fix grammar</button>`;
    pill.hidden = false;
    place(rect);
  }
  function place(rect) {
    const w = pill.offsetWidth;
    const x = Math.max(w / 2 + 8, Math.min(rect.left + rect.width / 2, innerWidth - w / 2 - 8));
    const y = rect.top - pill.offsetHeight - 10;
    pill.style.left = x + 'px';
    pill.style.top = (touchUI || y < 8 ? rect.bottom + 12 : y) + 'px';
  }
  function hidePill() { pill.hidden = true; pillPid = null; }

  const touchUI = matchMedia('(pointer: coarse)').matches;
  function checkSelection() {
    const sel = window.getSelection();
    if (!sel || sel.isCollapsed || !sel.toString().trim()) { if (!pill.contains(document.activeElement)) hidePill(); return; }
    const pid = pidFromNode(sel.anchorNode);
    if (!pid || pid !== pidFromNode(sel.focusNode)) return hidePill();
    showPill(sel.getRangeAt(0).getBoundingClientRect(), pid);
  }
  document.addEventListener('mouseup', (e) => {
    if (app.hidden || touchUI || pill.contains(e.target) || pop.contains(e.target) || panel.contains(e.target)) return;
    setTimeout(checkSelection, 0);
  });
  if (touchUI) {
    let selTimer;
    document.addEventListener('selectionchange', () => {
      if (app.hidden || pill.contains(document.activeElement)) return;
      clearTimeout(selTimer); selTimer = setTimeout(checkSelection, 350);
    });
  }
  document.addEventListener('mousedown', (e) => {
    if (!pill.contains(e.target) && !touchUI) hidePill();
    if (!pop.contains(e.target) && !e.target.closest('.hunk')) hidePop();
  });

  pill.addEventListener('click', (e) => {
    const b = e.target.closest('[data-pill]');
    if (!b) return;
    const a = b.dataset.pill, rect = pill.getBoundingClientRect();
    if (a === 'tone') {
      pill.innerHTML = `
        <button type="button" data-pill="formal">${dot('formal')}More formal</button>
        <button type="button" data-pill="warmer">${dot('warmer')}Warmer</button>
        <button type="button" data-pill="keep">${dot('keep')}Keep my wording</button>`;
      place(pillRect || rect);
      return;
    }
    if (a === 'ask') {
      pill.innerHTML = `<form id="askForm"><input name="q" autocomplete="off" placeholder="Ask Blaze to…"><button type="submit">↵</button></form>`;
      pill.querySelector('input').focus();
      return;
    }
    const pid = pillPid; window.getSelection().removeAllRanges();
    ask(pid === 'other' ? null : pid, a);
  });
  pill.addEventListener('submit', (e) => {
    e.preventDefault();
    const q = e.target.q.value.trim();
    if (!q) return;
    const pid = pillPid; window.getSelection().removeAllRanges();
    ask(pid === 'other' ? null : pid, keyFor(q, pid), q);
  });

  /* ---------- "/" command palette ---------- */
  const CMDS = ['rewrite', 'shorter', 'formal', 'warmer', 'grammar', 'keep', 'measurable'];
  let pIdx = 0, pTarget = 'why';
  function openPalette() {
    pTarget = S.mode !== 'empty' ? S.pid : lastPid;
    $('#paletteCtx').textContent = `/ commands · on “${PARAS[pTarget].title}”`;
    pIdx = 0; drawPalette(); palette.hidden = false; hidePill();
  }
  function drawPalette() {
    paletteList.innerHTML = CMDS.map((k, i) => `<li class="${i === pIdx ? 'on' : ''}" data-cmd="${k}">${dot(k)}${ACTIONS[k].label}</li>`).join('');
  }
  paletteList.addEventListener('mousemove', (e) => { const li = e.target.closest('li'); if (li) { const i = CMDS.indexOf(li.dataset.cmd); if (i !== pIdx) { pIdx = i; drawPalette(); } } });
  paletteList.addEventListener('click', (e) => { const li = e.target.closest('li'); if (li) { palette.hidden = true; ask(pTarget, li.dataset.cmd); } });
  palette.addEventListener('click', (e) => { if (e.target === palette) palette.hidden = true; });
  $('#paletteClose').addEventListener('click', () => { palette.hidden = true; });

  /* ---------- Keyboard ---------- */
  document.addEventListener('keydown', (e) => {
    if (app.hidden) return;
    const typing = /INPUT|TEXTAREA/.test(document.activeElement.tagName);
    if (!palette.hidden) {
      if (e.key === 'ArrowDown') { pIdx = (pIdx + 1) % CMDS.length; drawPalette(); e.preventDefault(); }
      else if (e.key === 'ArrowUp') { pIdx = (pIdx - 1 + CMDS.length) % CMDS.length; drawPalette(); e.preventDefault(); }
      else if (e.key === 'Enter') { palette.hidden = true; ask(pTarget, CMDS[pIdx]); e.preventDefault(); }
      else if (e.key === 'Escape') palette.hidden = true;
      return;
    }
    if (!keysModal.hidden) { if (e.key === 'Escape') keysModal.hidden = true; return; }
    if (e.key === 'Escape') {
      if (typing) { document.activeElement.blur(); hidePill(); return; }
      if (!pill.hidden) return hidePill();
      if (!pop.hidden) return hidePop();
      if (S.mode === 'thinking') return cancelThinking();
      return rejectAll();
    }
    if (typing) return;
    if (e.key === '/' ) { e.preventDefault(); openPalette(); }
    else if (e.key === '?') keysModal.hidden = false;
    else if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); acceptAll(); }
    else if ((e.key === 'z' || e.key === 'Z') && (e.metaKey || e.ctrlKey) && !e.shiftKey) { e.preventDefault(); undo(); }
  });

  /* ---------- Shortcuts dialog ---------- */
  const keysModal = $('#keysModal');
  $('#keysBtn').addEventListener('click', () => { keysModal.hidden = false; });
  $('#cmdBtn').addEventListener('click', () => openPalette());
  $('#keysClose').addEventListener('click', () => { keysModal.hidden = true; });
  keysModal.addEventListener('click', (e) => { if (e.target === keysModal) keysModal.hidden = true; });

  /* ---------- Toast ---------- */
  const toastEl = $('#toast');
  let toastTimer;
  function toast(msg, withUndo) {
    toastEl.innerHTML = esc(msg) + (withUndo ? '<button type="button" id="toastUndo">Undo</button>' : '');
    toastEl.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toastEl.classList.remove('show'), withUndo ? 5000 : 2600);
  }
  toastEl.addEventListener('click', (e) => { if (e.target.id === 'toastUndo') { undo(); } });

  /* ---------- Intro ↔ editor ---------- */
  const app = $('#app'), intro = $('#intro');
  function route() {
    const editor = location.hash === '#editor';
    intro.hidden = editor; app.hidden = !editor;
    hidePill(); hidePop(); palette.hidden = true;
    if (window.BlazeIntro) editor ? BlazeIntro.stop() : BlazeIntro.play();
    window.scrollTo(0, 0);
  }
  window.addEventListener('hashchange', route);
  renderPanel();
  route();
})();
</script>
</body>
</html>

