    'it is working': /know it's working/i,
    'about tickets': /ticket/i,
    'about speed': /time|sooner|faster|within|hours/i,
  },
  'markdown-formal': {
    'bold term': /\*\*median first response\*\*/,
    '9 hours': /9 hours/,
    'as of today': /today|currently/i,
