import type { Editor } from '@tiptap/core'
import { Markdown } from '@tiptap/markdown'
import type { Node as ProseMirrorNode } from '@tiptap/pm/model'
import StarterKit from '@tiptap/starter-kit'
import { MAX_CONTEXT_CHARS } from '../../shared/contract'
import type { SuggestContext, SuggestTarget } from '../../shared/contract'

export const EDITOR_EXTENSIONS = [
  StarterKit.configure({ link: { openOnClick: false } }),
  Markdown,
]

/** What a suggestion is about: a place in the document and its text. */
export interface SuggestionPlace {
  kind: SuggestTarget
  /** The range the suggestion would replace. */
  from: number
  to: number
  /** The block or blocks an edit would make the suggestion stale. */
  guardFrom: number
  guardTo: number
  /** True when the range sits inside one block rather than covering whole blocks. */
  inline: boolean
  markdown: string
  /** Shown in the card, such as "Why now". */
  title: string
  context: SuggestContext | null
}

function serialize(editor: Editor, content: unknown[]): string {
  const markdown = editor.markdown
  if (!markdown) throw new Error('The Markdown extension is not loaded')
  return markdown.serialize({ type: 'doc', content: content as never[] }).trim()
}

/** Rewrites Markdown through the editor, so syntax choices don't show as changes. */
export function normalizeMarkdown(editor: Editor, text: string): string {
  const markdown = editor.markdown
  if (!markdown) throw new Error('The Markdown extension is not loaded')
  return markdown.serialize(markdown.parse(text)).trim()
}

function blocksToMarkdown(editor: Editor, blocks: ProseMirrorNode[]): string {
  return serialize(editor, blocks.map((block) => block.toJSON()))
}

interface TopLevelBlock {
  node: ProseMirrorNode
  from: number
  to: number
}

function topLevelBlocks(doc: ProseMirrorNode): TopLevelBlock[] {
  const blocks: TopLevelBlock[] = []
  doc.forEach((node, offset) => blocks.push({ node, from: offset, to: offset + node.nodeSize }))
  return blocks
}

function isHeading(block: TopLevelBlock | undefined): boolean {
  return block?.node.type.name === 'heading'
}

function headingLevel(block: TopLevelBlock): number {
  return Number(block.node.attrs.level)
}

/**
 * The blocks a heading owns. A title (level 1) owns only the text before the
 * next heading, otherwise it would own the whole document.
 */
function sectionEnd(blocks: TopLevelBlock[], headingIndex: number): number {
  const heading = blocks[headingIndex]
  if (!heading) return headingIndex + 1
  const level = headingLevel(heading)
  for (let i = headingIndex + 1; i < blocks.length; i += 1) {
    const block = blocks[i]
    if (block && isHeading(block) && (level === 1 || headingLevel(block) <= level)) return i
  }
  return blocks.length
}

function headingIndexAt(blocks: TopLevelBlock[], blockIndex: number): number {
  for (let i = blockIndex; i >= 0; i -= 1) {
    if (isHeading(blocks[i])) return i
  }
  return -1
}

function truncate(text: string, keep: 'start' | 'end'): string | null {
  if (text === '') return null
  if (text.length <= MAX_CONTEXT_CHARS) return text
  return keep === 'start' ? text.slice(0, MAX_CONTEXT_CHARS) : text.slice(-MAX_CONTEXT_CHARS)
}

/**
 * The section around a selection, read-only for the model. When the document
 * has no heading, the neighbouring blocks stand in for it.
 */
function contextAround(
  editor: Editor,
  blocks: TopLevelBlock[],
  firstIndex: number,
  lastIndex: number,
): SuggestContext {
  const headingIndex = headingIndexAt(blocks, firstIndex)
  const heading = blocks[headingIndex]
  const start = headingIndex === -1 ? Math.max(0, firstIndex - 1) : headingIndex + 1
  const end =
    headingIndex === -1 ? Math.min(blocks.length, lastIndex + 2) : sectionEnd(blocks, headingIndex)

  const toText = (from: number, to: number) =>
    blocksToMarkdown(editor, blocks.slice(from, to).map((block) => block.node))

  return {
    heading: heading ? heading.node.textContent : null,
    before: truncate(toText(start, firstIndex), 'end'),
    after: truncate(toText(lastIndex + 1, end), 'start'),
  }
}

function blockIndexAt(blocks: TopLevelBlock[], position: number): number {
  return blocks.findIndex((block) => position >= block.from && position < block.to)
}

/** The user's selection, or null if there's nothing to work on. */
export function placeFromSelection(editor: Editor): SuggestionPlace | null {
  const { state } = editor
  const { $from, $to, empty } = state.selection
  if (empty) return null

  const blocks = topLevelBlocks(state.doc)
  const firstIndex = blockIndexAt(blocks, state.selection.from)
  const lastIndex = blockIndexAt(blocks, state.selection.to - 1)
  const first = blocks[firstIndex]
  const last = blocks[lastIndex]
  if (!first || !last) return null

  const heading = blocks[headingIndexAt(blocks, firstIndex)]
  const title = heading ? heading.node.textContent : 'Selection'
  const context = contextAround(editor, blocks, firstIndex, lastIndex)

  if ($from.sameParent($to) && $from.parent.isTextblock) {
    // Edge spaces stay out of the range: the model would drop them, and two
    // words would run together on accept.
    const selected = state.doc.textBetween(state.selection.from, state.selection.to)
    if (selected.trim() === '') return null
    const from = state.selection.from + (selected.length - selected.trimStart().length)
    const to = state.selection.to - (selected.length - selected.trimEnd().length)

    const parentStart = $from.start()
    const content = state.doc.slice(from, to).content.toJSON() as unknown[]
    return {
      kind: 'selection',
      from,
      to,
      guardFrom: parentStart,
      guardTo: parentStart + $from.parent.content.size,
      inline: true,
      markdown: serialize(editor, [{ type: 'paragraph', content }]),
      title,
      context,
    }
  }

  // Across blocks, the whole blocks are replaced so their structure stays valid.
  return {
    kind: 'selection',
    from: first.from,
    to: last.to,
    guardFrom: first.from,
    guardTo: last.to,
    inline: false,
    markdown: blocksToMarkdown(editor, blocks.slice(firstIndex, lastIndex + 1).map((block) => block.node)),
    title,
    context,
  }
}

/**
 * The section holding a position, without its heading, or null if it has no
 * text. With no usable heading it falls back to the current block, so this
 * never hands the whole document to the model.
 */
export function placeFromSection(editor: Editor, position: number): SuggestionPlace | null {
  const blocks = topLevelBlocks(editor.state.doc)
  const blockIndex = blockIndexAt(blocks, Math.min(position, editor.state.doc.content.size - 1))
  if (blockIndex === -1) return null

  const headingIndex = headingIndexAt(blocks, blockIndex)
  const heading = blocks[headingIndex]
  const start = headingIndex + 1
  const end = heading ? sectionEnd(blocks, headingIndex) : blocks.length
  const body = blocks.slice(start, end)
  const bodyBlocks = blocks.filter((block) => !isHeading(block))

  const coversWholeDocument = body.length > 1 && body.filter((block) => !isHeading(block)).length === bodyBlocks.length
  const chosen = !heading || coversWholeDocument ? blocks.slice(blockIndex, blockIndex + 1) : body

  const text = chosen.map((block) => block.node.textContent).join('').trim()
  const first = chosen[0]
  const last = chosen.at(-1)
  if (text === '' || !first || !last || chosen.every(isHeading)) return null

  return {
    kind: 'section',
    from: first.from,
    to: last.to,
    guardFrom: first.from,
    guardTo: last.to,
    inline: false,
    markdown: blocksToMarkdown(editor, chosen.map((block) => block.node)),
    title: heading ? heading.node.textContent : 'Paragraph',
    context: { heading: heading ? heading.node.textContent : null, before: null, after: null },
  }
}

/** The section under a heading with this exact text, for "Try one" prompts. */
export function placeFromHeading(editor: Editor, headingText: string): SuggestionPlace | null {
  const heading = topLevelBlocks(editor.state.doc).find(
    (block) => isHeading(block) && block.node.textContent === headingText,
  )
  return heading ? placeFromSection(editor, heading.from) : null
}

// @vitest-environment jsdom
import { Editor } from '@tiptap/core'
import { afterEach, describe, expect, it } from 'vitest'
import { SAMPLE_DOCUMENT } from '../sampleDocument'
import {
  EDITOR_EXTENSIONS,
  normalizeMarkdown,
  placeFromHeading,
  placeFromSection,
  placeFromSelection,
} from './editorDocument'

const editors: Editor[] = []

function editorWith(markdown: string): Editor {
  const editor = new Editor({
    extensions: EDITOR_EXTENSIONS,
    content: markdown,
    contentType: 'markdown',
  })
  editors.push(editor)
  return editor
}

/** Selects the first occurrence of some text inside one block. */
function selectText(editor: Editor, text: string): void {
  let found: { from: number; to: number } | null = null
  editor.state.doc.descendants((node, position) => {
    if (found || !node.isTextblock) return true
    const index = node.textContent.indexOf(text)
    if (index >= 0) found = { from: position + 1 + index, to: position + 1 + index + text.length }
    return false
  })
  if (!found) throw new Error(`Text not found: ${text}`)
  editor.commands.setTextSelection(found)
}

function positionOf(editor: Editor, text: string): number {
  selectText(editor, text)
  return editor.state.selection.from
}

afterEach(() => {
  editors.splice(0).forEach((editor) => editor.destroy())
})

const RICH = `# Title

## Plans

Read **the plan** and see [the docs](https://example.com/docs) today.

- First *item*
- Second item

## Later

More text.
`

describe('Markdown round trip', () => {
  it('markdown round trip keeps headings, lists, bold and links', () => {
    const output = editorWith(RICH).getMarkdown()
    expect(output).toContain('# Title')
    expect(output).toContain('## Plans')
    expect(output).toContain('**the plan**')
    expect(output).toContain('[the docs](https://example.com/docs)')
    expect(output).toContain('- First *item*')
    expect(output).toContain('- Second item')
  })

  it('the sample document round trips without losing text', () => {
    const output = editorWith(SAMPLE_DOCUMENT).getMarkdown()
    expect(output).toContain('# AI rollout plan — Bluefield support team')
    expect(output).toContain("We'll know it's working when tickets get answered faster.")
    expect(output).toContain('- A shared knowledge base')
  })

  it('a placeholder in square brackets survives normalizing', () => {
    const text = 'Response time drops from [X] hours to [Y]% within [Z] weeks.'
    expect(normalizeMarkdown(editorWith(RICH), text)).toBe(text)
  })

  it('normalizing removes differences in Markdown syntax', () => {
    const editor = editorWith(RICH)
    expect(normalizeMarkdown(editor, '* one\n* two')).toBe(normalizeMarkdown(editor, '- one\n- two'))
    expect(normalizeMarkdown(editor, '__bold__')).toBe(normalizeMarkdown(editor, '**bold**'))
  })
})

describe('placeFromSelection', () => {
  it('a selection request sends only the selected Markdown', () => {
    const editor = editorWith(RICH)
    selectText(editor, 'Read the plan and see')
    const place = placeFromSelection(editor)
    expect(place?.kind).toBe('selection')
    expect(place?.inline).toBe(true)
    expect(place?.markdown).toBe('Read **the plan** and see')
  })

  it('a selected link keeps its URL in the Markdown', () => {
    const editor = editorWith(RICH)
    selectText(editor, 'the docs')
    expect(placeFromSelection(editor)?.markdown).toBe('[the docs](https://example.com/docs)')
  })

  it('a selection request includes its section as context', () => {
    const editor = editorWith(SAMPLE_DOCUMENT)
    selectText(editor, 'We are going to log every suggestion')
    const place = placeFromSelection(editor)
    expect(place?.title).toBe("How we'll keep it safe")
    expect(place?.context?.heading).toBe("How we'll keep it safe")
    // One paragraph holds the whole section, so nothing else is around it.
    expect(place?.context?.before).toBeNull()
  })

  it('context comes from the same section only', () => {
    const editor = editorWith('## One\n\nOther section.\n\n## Two\n\nBefore it.\n\nThe target.\n\nAfter it.\n\n## Three\n\nFar away.')
    selectText(editor, 'The target.')
    const context = placeFromSelection(editor)?.context
    expect(context).toEqual({ heading: 'Two', before: 'Before it.', after: 'After it.' })
  })

  it('edge spaces stay out of the replaced range', () => {
    const editor = editorWith('Keep these words together.')
    selectText(editor, ' these words ')
    const place = placeFromSelection(editor)
    expect(place?.markdown).toBe('these words')
    expect(editor.state.doc.textBetween(place?.from ?? 0, place?.to ?? 0)).toBe('these words')
  })

  it('an empty selection has no place', () => {
    const editor = editorWith(RICH)
    editor.commands.setTextSelection(3)
    expect(placeFromSelection(editor)).toBeNull()
  })

  it('a selection across blocks covers the whole blocks', () => {
    const editor = editorWith('## Head\n\nFirst paragraph.\n\nSecond paragraph.\n\nThird paragraph.')
    selectText(editor, 'paragraph.')
    const from = editor.state.selection.from
    selectText(editor, 'Second')
    editor.commands.setTextSelection({ from, to: editor.state.selection.to })
    const place = placeFromSelection(editor)
    expect(place?.inline).toBe(false)
    expect(place?.markdown).toBe('First paragraph.\n\nSecond paragraph.')
    expect(place?.context?.after).toBe('Third paragraph.')
  })
})

describe('placeFromSection', () => {
  it("the current section is the blocks under the cursor's heading", () => {
    const editor = editorWith(RICH)
    const place = placeFromSection(editor, positionOf(editor, 'Second item'))
    expect(place?.kind).toBe('section')
    expect(place?.title).toBe('Plans')
    expect(place?.markdown).toContain('**the plan**')
    expect(place?.markdown).toContain('- Second item')
  })

  it('a section command sends only that section', () => {
    const editor = editorWith(RICH)
    const markdown = placeFromSection(editor, positionOf(editor, 'the plan'))?.markdown ?? ''
    expect(markdown).not.toContain('Plans')
    expect(markdown).not.toContain('Title')
    expect(markdown).not.toContain('More text')
  })

  it('a cursor on a heading means the section under it', () => {
    const editor = editorWith(RICH)
    expect(placeFromSection(editor, positionOf(editor, 'Later'))?.markdown).toBe('More text.')
  })

  it('a section includes its subheadings', () => {
    const editor = editorWith('## Parent\n\nIntro.\n\n### Child\n\nDetail.\n\n## Next\n\nOther.')
    const markdown = placeFromSection(editor, positionOf(editor, 'Intro'))?.markdown ?? ''
    expect(markdown).toContain('### Child')
    expect(markdown).toContain('Detail.')
    expect(markdown).not.toContain('Other')
  })

  it('a title with no text of its own has no target', () => {
    const editor = editorWith(RICH)
    expect(placeFromSection(editor, positionOf(editor, 'Title'))).toBeNull()
  })

  it('an empty section has no target', () => {
    const editor = editorWith('## Empty\n\n## Next\n\nText.')
    expect(placeFromSection(editor, positionOf(editor, 'Empty'))).toBeNull()
  })

  it('a document with no headings targets the current paragraph, not all of it', () => {
    const editor = editorWith('First paragraph.\n\nSecond paragraph.\n\nThird paragraph.')
    const place = placeFromSection(editor, positionOf(editor, 'Second'))
    expect(place?.markdown).toBe('Second paragraph.')
  })

  it('a document with only a title targets the current paragraph, not all of it', () => {
    const editor = editorWith('# Title\n\nFirst paragraph.\n\nSecond paragraph.')
    expect(placeFromSection(editor, positionOf(editor, 'Second'))?.markdown).toBe('Second paragraph.')
  })
})

describe('placeFromHeading', () => {
  it('finds a section by its heading text', () => {
    const editor = editorWith(SAMPLE_DOCUMENT)
    expect(placeFromHeading(editor, 'Success metrics')?.markdown).toBe(
      "We'll know it's working when tickets get answered faster.",
    )
  })

  it('finds nothing when the heading is gone', () => {
    expect(placeFromHeading(editorWith(RICH), 'Success metrics')).toBeNull()
  })
})

describe('text the user just typed', () => {
  it('suggestions work on text the user just typed', () => {
    const editor = editorWith('')
    editor.commands.insertContent('A sentence I just typed with **bold** words.', { contentType: 'markdown' })
    selectText(editor, 'A sentence I just typed')
    const place = placeFromSelection(editor)
    expect(place?.kind).toBe('selection')
    expect(place?.markdown).toBe('A sentence I just typed')
    expect(placeFromSection(editor, positionOf(editor, 'just typed'))?.markdown).toBe(
      'A sentence I just typed with **bold** words.',
    )
  })
})

