  | { ok: false; aborted: false; code: ClientErrorCode; message: string }

function failure(code: ClientErrorCode, message: string): SuggestResult {
  return { ok: false, aborted: false, code, message }
}

function isAbort(error: unknown): boolean {
  return error instanceof DOMException && error.name === 'AbortError'
}

/** The only place in the UI that talks to the network. */
export async function requestSuggestion(
  request: SuggestRequest,
  signal: AbortSignal,
  fetchFn: typeof fetch = fetch,
): Promise<SuggestResult> {
  try {
    const response = await fetchFn(SUGGEST_PATH, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(request),
      signal,
    })
    const body = (await response.json()) as Suggestion | SuggestErrorBody

    if ('error' in body) return failure(body.error.code, body.error.message)
    if (!response.ok) return failure('upstream_error', 'The model service had a problem. Try again.')
    return { ok: true, suggestion: body }
  } catch (error) {
    if (isAbort(error)) return { ok: false, aborted: true }
    return failure('network', "Couldn't reach the server. Check that it's running and try again.")
  }
}

import { useCallback, useReducer, useRef } from 'react'
import { requestSuggestion } from '../api/suggestClient'
import type { ClientErrorCode } from '../api/suggestClient'
import type { SuggestRequest, Suggestion } from '../../shared/contract'

export type AiRequestState =
  | { status: 'idle' }
  | { status: 'loading'; requestId: number }
  | { status: 'success'; requestId: number; suggestion: Suggestion }
  | { status: 'error'; requestId: number; code: ClientErrorCode; message: string }

export type AiRequestAction =
  | { type: 'start'; requestId: number }
  | { type: 'succeed'; requestId: number; suggestion: Suggestion }
  | { type: 'fail'; requestId: number; code: ClientErrorCode; message: string }
  | { type: 'reset' }

export const INITIAL_AI_REQUEST: AiRequestState = { status: 'idle' }

/** A reply only counts if it answers the request still in flight. */
export function aiRequestReducer(state: AiRequestState, action: AiRequestAction): AiRequestState {
  switch (action.type) {
    case 'start':
      return { status: 'loading', requestId: action.requestId }
    case 'succeed':
      if (state.status !== 'loading' || state.requestId !== action.requestId) return state
      return { status: 'success', requestId: action.requestId, suggestion: action.suggestion }
    case 'fail':
      if (state.status !== 'loading' || state.requestId !== action.requestId) return state
      return {
        status: 'error',
        requestId: action.requestId,
        code: action.code,
        message: action.message,
      }
    case 'reset':
      return INITIAL_AI_REQUEST
  }
}

export function useAiRequest() {
  const [state, dispatch] = useReducer(aiRequestReducer, INITIAL_AI_REQUEST)
  const inFlight = useRef<AbortController | null>(null)
  const lastRequestId = useRef(0)

  /** Starts a request, replacing any in flight. Null means it was replaced or cancelled. */
  const run = useCallback(async (request: SuggestRequest): Promise<Suggestion | null> => {
    inFlight.current?.abort()
    const controller = new AbortController()
    inFlight.current = controller
    lastRequestId.current += 1
    const requestId = lastRequestId.current

    dispatch({ type: 'start', requestId })
    const result = await requestSuggestion(request, controller.signal)

    if (result.ok) {
      dispatch({ type: 'succeed', requestId, suggestion: result.suggestion })
      return lastRequestId.current === requestId ? result.suggestion : null
    }
    if (!result.aborted) {
      dispatch({ type: 'fail', requestId, code: result.code, message: result.message })
    }
    return null
  }, [])

  const reset = useCallback(() => {
    inFlight.current?.abort()
    inFlight.current = null
    lastRequestId.current += 1
    dispatch({ type: 'reset' })
  }, [])

  return { state, run, reset }
}

import { describe, expect, it } from 'vitest'
import { aiRequestReducer, INITIAL_AI_REQUEST } from './useAiRequest'

const suggestion = { rewrite: 'Short.', rationale: 'Cut filler.' }

describe('aiRequestReducer', () => {
  it('goes from idle to loading to success', () => {
    const loading = aiRequestReducer(INITIAL_AI_REQUEST, { type: 'start', requestId: 1 })
    expect(loading.status).toBe('loading')
    const done = aiRequestReducer(loading, { type: 'succeed', requestId: 1, suggestion })
    expect(done).toEqual({ status: 'success', requestId: 1, suggestion })
  })

  it('goes from loading to error', () => {
    const loading = aiRequestReducer(INITIAL_AI_REQUEST, { type: 'start', requestId: 1 })
    const failed = aiRequestReducer(loading, {
      type: 'fail',
      requestId: 1,
      code: 'network',
      message: 'Offline',
    })
    expect(failed).toMatchObject({ status: 'error', code: 'network', message: 'Offline' })
  })

  it('a stale response is ignored', () => {
    const second = aiRequestReducer(
      aiRequestReducer(INITIAL_AI_REQUEST, { type: 'start', requestId: 1 }),
      { type: 'start', requestId: 2 },
    )
    expect(aiRequestReducer(second, { type: 'succeed', requestId: 1, suggestion })).toBe(second)
    expect(
      aiRequestReducer(second, { type: 'fail', requestId: 1, code: 'network', message: 'Offline' }),
    ).toBe(second)
  })

  it('a response after a reset is ignored', () => {
    const reset = aiRequestReducer(
      aiRequestReducer(INITIAL_AI_REQUEST, { type: 'start', requestId: 1 }),
      { type: 'reset' },
    )
    expect(aiRequestReducer(reset, { type: 'succeed', requestId: 1, suggestion })).toEqual(
      INITIAL_AI_REQUEST,
    )
  })
})

import { Extension } from '@tiptap/core'
import type { Editor } from '@tiptap/core'
import { Plugin, PluginKey } from '@tiptap/pm/state'
import { Decoration, DecorationSet } from '@tiptap/pm/view'

const highlightKey = new PluginKey<DecorationSet>('targetHighlight')

export interface HighlightRange {
  from: number
  to: number
}

/**
 * Marks what a suggestion is about without touching the document: decorations
 * are drawn over the text and never saved in it.
 */
export const TargetHighlight = Extension.create({
  name: 'targetHighlight',

  addProseMirrorPlugins() {
    return [
      new Plugin<DecorationSet>({
        key: highlightKey,
        state: {
          init: () => DecorationSet.empty,
          apply(tr, current) {
            const next = tr.getMeta(highlightKey) as DecorationSet | undefined
            return next ?? current.map(tr.mapping, tr.doc)
          },
        },
        props: {
          decorations: (state) => highlightKey.getState(state),
        },
      }),
    ]
  },
})

export function setTargetHighlight(editor: Editor, range: HighlightRange | null): void {
  const { doc, tr } = editor.state
  const decorations: Decoration[] = []

  if (range) {
    decorations.push(Decoration.inline(range.from, range.to, { class: 'blaze-target' }))
    doc.forEach((node, offset) => {
      const end = offset + node.nodeSize
      if (offset < range.to && end > range.from) {
        decorations.push(Decoration.node(offset, end, { class: 'blaze-target-block' }))
      }
    })
  }

  editor.view.dispatch(tr.setMeta(highlightKey, DecorationSet.create(doc, decorations)))
}

