import type { SuggestionDiff } from './diff'
import type { SuggestionPlace } from './editorDocument'

/** One answer from the model. Refining adds another. */
export interface Iteration {
  label: string
  rewrite: string
  rationale: string
  diff: SuggestionDiff
}

/** One suggestion under review, from the first ask until it's settled. */
export interface Session {
  place: SuggestionPlace
  /** The action in flight or last asked for. */
  label: string
  iterations: Iteration[]
  current: number
}

export type SessionAction =
  | { type: 'begin'; place: SuggestionPlace; label: string }
  | { type: 'addIteration'; iteration: Iteration }
  | { type: 'end' }

export function sessionReducer(session: Session | null, action: SessionAction): Session | null {
  switch (action.type) {
    case 'begin':
      return { place: action.place, label: action.label, iterations: [], current: 0 }
    case 'addIteration':
      if (!session) return null
      return {
        ...session,
        iterations: [...session.iterations, action.iteration],
        current: session.iterations.length,
      }
    case 'end':
      return null
  }
}

export function currentIteration(session: Session): Iteration | undefined {
  return session.iterations[session.current]
}

import { useEditor } from '@tiptap/react'
import { EDITOR_EXTENSIONS } from '../lib/editorDocument'
import { SAMPLE_DOCUMENT } from '../sampleDocument'

export function useBlazeEditor() {
  return useEditor({
    extensions: EDITOR_EXTENSIONS,
    content: SAMPLE_DOCUMENT,
    contentType: 'markdown',
    editorProps: {
      attributes: { 'aria-label': 'Document', spellcheck: 'true' },
    },
  })
}

import type { Editor } from '@tiptap/core'
import { useCallback, useEffect, useRef, useState } from 'react'

export type PillView = 'actions' | 'tone' | 'ask'

export interface PillPosition {
  /** Centre of the selection, in viewport pixels. */
  left: number
  top: number
}

/** Where the pill sits and which of its views is open. */
export function useSelectionPill(editor: Editor) {
  const [position, setPosition] = useState<PillPosition | null>(null)
  const [view, setView] = useState<PillView>('actions')
  const [askText, setAskText] = useState('')
  const dragging = useRef(false)

  const reset = useCallback(() => {
    setPosition(null)
    setView('actions')
    setAskText('')
  }, [])

  useEffect(() => {
    const update = () => {
      if (dragging.current) return
      const { from, to, empty } = editor.state.selection
      if (empty || editor.state.doc.textBetween(from, to, ' ').trim() === '') {
        reset()
        return
      }
      const start = editor.view.coordsAtPos(from)
      const end = editor.view.coordsAtPos(to)
      setPosition({ left: (start.left + end.right) / 2, top: Math.min(start.top, end.top) })
    }
    const startDrag = () => {
      dragging.current = true
      reset()
    }
    const endDrag = () => {
      if (!dragging.current) return
      dragging.current = false
      update()
    }

    const dom = editor.view.dom
    editor.on('selectionUpdate', update)
    dom.addEventListener('mousedown', startDrag)
    window.addEventListener('mouseup', endDrag)
    return () => {
      editor.off('selectionUpdate', update)
      dom.removeEventListener('mousedown', startDrag)
      window.removeEventListener('mouseup', endDrag)
    }
  }, [editor, reset])

  return { position, view, setView, askText, setAskText, close: reset }
}

import type { Editor } from '@tiptap/core'
import { useCallback, useReducer } from 'react'
import type { SuggestRequest } from '../../shared/contract'
import type { Command } from '../constants'
import { computeDiff } from '../lib/diff'
import { normalizeMarkdown, placeFromSelection } from '../lib/editorDocument'
import type { SuggestionPlace } from '../lib/editorDocument'
import { currentIteration, sessionReducer } from '../lib/suggestionSession'
import { setTargetHighlight } from '../lib/targetHighlight'
import { useAiRequest } from './useAiRequest'

export type CardView =
  | { kind: 'idle' }
  | { kind: 'loading'; title: string; label: string }
  | { kind: 'error'; title: string; message: string }
  | { kind: 'review'; title: string; label: string; rationale: string; diff: ReturnType<typeof computeDiff> }

function buildRequest(place: SuggestionPlace, instruction: string, currentSuggestion: string | null): SuggestRequest {
  return {
    selection: place.markdown,
    target: place.kind,
    instruction,
    currentSuggestion,
    context: place.context,
  }
}

/** Free text from an Ask field is the instruction, and its own short label. */
export function askCommand(text: string): Command {
  const instruction = text.trim()
  return { id: 'ask', label: `“${instruction}”`, instruction }
}

export function useSuggestion(editor: Editor) {
  const ai = useAiRequest()
  const { run } = ai
  const [session, dispatch] = useReducer(sessionReducer, null)

  const askAbout = useCallback(
    async (place: SuggestionPlace, command: Command) => {
      dispatch({ type: 'begin', place, label: command.label })
      setTargetHighlight(editor, place)

      const suggestion = await run(buildRequest(place, command.instruction, null))
      if (!suggestion) return

      const rewrite = normalizeMarkdown(editor, suggestion.rewrite)
      dispatch({
        type: 'addIteration',
        iteration: {
          label: command.label,
          rewrite,
          rationale: suggestion.rationale,
          diff: computeDiff(place.markdown, rewrite),
        },
      })
    },
    [editor, run],
  )

  const askAboutSelection = useCallback(
    (command: Command) => {
      const place = placeFromSelection(editor)
      if (place) void askAbout(place, command)
    },
    [askAbout, editor],
  )

  let cardView: CardView = { kind: 'idle' }
  if (session) {
    const iteration = currentIteration(session)
    const { title } = session.place
    if (iteration) {
      cardView = {
        kind: 'review',
        title,
        label: iteration.label,
        rationale: iteration.rationale,
        diff: iteration.diff,
      }
    } else if (ai.state.status === 'error') {
      cardView = { kind: 'error', title, message: ai.state.message }
    } else {
      cardView = { kind: 'loading', title, label: session.label }
    }
  }

  return { cardView, askAboutSelection }
}

