import { useCallback, useEffect, useRef, useState } from 'react'

export interface Notice {
  message: string
  /** Offers an Undo button when the notice follows a change to the document. */
  undoable: boolean
}

const VISIBLE_MS = 6000

export function useNotice() {
  const [notice, setNotice] = useState<Notice | null>(null)
  const timer = useRef<number | undefined>(undefined)

  const dismiss = useCallback(() => {
    window.clearTimeout(timer.current)
    setNotice(null)
  }, [])

  const show = useCallback((message: string, undoable = false) => {
    window.clearTimeout(timer.current)
    setNotice({ message, undoable })
    timer.current = window.setTimeout(() => setNotice(null), VISIBLE_MS)
  }, [])

  useEffect(() => () => window.clearTimeout(timer.current), [])

  return { notice, show, dismiss }
}

import type { Editor } from '@tiptap/core'
import type { Transaction } from '@tiptap/pm/state'
import { useCallback, useEffect, useReducer } from 'react'
import type { SuggestRequest } from '../../shared/contract'
import type { Command } from '../constants'
import { APPLY_META, applyMarkdown, mapPlace } from '../lib/applySuggestion'
import { applyDecisions, computeDiff, keepAll } from '../lib/diff'
import type { ChangeDecision, SuggestionDiff } from '../lib/diff'
import { normalizeMarkdown, placeFromSelection } from '../lib/editorDocument'
import type { SuggestionPlace } from '../lib/editorDocument'
import { currentIteration, sessionReducer } from '../lib/suggestionSession'
import { setTargetHighlight } from '../lib/targetHighlight'
import { useAiRequest } from './useAiRequest'

export interface ReviewView {
  kind: 'review'
  title: string
  label: string
  rationale: string
  diff: SuggestionDiff
  decisions: ReadonlyMap<number, ChangeDecision>
  activeChange: number
}

export type CardView =
  | { kind: 'idle' }
  | { kind: 'loading'; title: string; label: string }
  | { kind: 'error'; title: string; message: string }
  | ReviewView

function buildRequest(place: SuggestionPlace, instruction: string, currentSuggestion: string | null): SuggestRequest {
  return {
    selection: place.markdown,
    target: place.kind,
    instruction,
    currentSuggestion,
    context: place.context,
  }
}

/** Free text from an Ask field is the instruction, and its own short label. */
export function askCommand(text: string): Command {
  const instruction = text.trim()
  return { id: 'ask', label: `“${instruction}”`, instruction }
}

function plural(count: number, noun: string): string {
  return `${count} ${noun}${count === 1 ? '' : 's'}`
}

export function useSuggestion(editor: Editor, showNotice: (message: string, undoable?: boolean) => void) {
  const ai = useAiRequest()
  const { run, reset } = ai
  const [session, dispatch] = useReducer(sessionReducer, null)

  const endSession = useCallback(() => {
    reset()
    dispatch({ type: 'end' })
    setTargetHighlight(editor, null)
  }, [editor, reset])

  // Follows the place through edits elsewhere, and drops the suggestion if its
  // own paragraph changed. Transactions catch paste and undo, not just typing.
  const place = session?.place
  useEffect(() => {
    if (!place) return
    const onTransaction = ({ transaction }: { transaction: Transaction }) => {
      if (!transaction.docChanged || transaction.getMeta(APPLY_META)) return
      const mapped = mapPlace(place, transaction)
      if (mapped.touched) {
        endSession()
        showNotice('You edited this text, so the suggestion was discarded.')
      } else {
        dispatch({ type: 'movePlace', place: mapped.place })
      }
    }
    editor.on('transaction', onTransaction)
    return () => {
      editor.off('transaction', onTransaction)
    }
  }, [editor, endSession, place, showNotice])

  const askAbout = useCallback(
    async (target: SuggestionPlace, command: Command) => {
      dispatch({ type: 'begin', place: target, label: command.label })
      setTargetHighlight(editor, target)

      const suggestion = await run(buildRequest(target, command.instruction, null))
      if (!suggestion) return

      const rewrite = normalizeMarkdown(editor, suggestion.rewrite)
      dispatch({
        type: 'addIteration',
        iteration: {
          label: command.label,
          rewrite,
          rationale: suggestion.rationale,
          diff: computeDiff(target.markdown, rewrite),
        },
      })
    },
    [editor, run],
  )

  const askAboutSelection = useCallback(
    (command: Command) => {
      const target = placeFromSelection(editor)
      if (target) void askAbout(target, command)
    },
    [askAbout, editor],
  )

  const iteration = session ? currentIteration(session) : undefined

  const settle = useCallback(
    (decisions: ReadonlyMap<number, ChangeDecision>) => {
      if (!session || !iteration) return
      const kept = [...decisions.values()].filter((decision) => decision === 'keep').length
      const markdown = applyDecisions(iteration.diff, decisions)

      endSession()
      if (kept === 0 || markdown === session.place.markdown) {
        showNotice('No changes applied. Your text is unchanged.')
        return
      }
      applyMarkdown(editor, session.place, markdown)
      showNotice(`Applied ${plural(kept, 'change')}.`, true)
    },
    [editor, endSession, iteration, session, showNotice],
  )

  const acceptAll = useCallback(() => {
    if (iteration) settle(keepAll(iteration.diff))
  }, [iteration, settle])

  const applyDecided = useCallback(() => {
    if (session) settle(session.decisions)
  }, [session, settle])

  const rejectAll = useCallback(() => {
    endSession()
    showNotice('Suggestion rejected. Your text is unchanged.')
  }, [endSession, showNotice])

  const close = useCallback(() => endSession(), [endSession])

  const decide = useCallback((id: number, decision: ChangeDecision) => {
    dispatch({ type: 'decide', id, decision })
  }, [])
  const selectChange = useCallback((id: number) => dispatch({ type: 'selectChange', id }), [])
  const stepChange = useCallback((delta: 1 | -1) => dispatch({ type: 'stepChange', delta }), [])

  let cardView: CardView = { kind: 'idle' }
  if (session) {
    const { title } = session.place
    if (iteration) {
      cardView = {
        kind: 'review',
        title,
        label: iteration.label,
        rationale: iteration.rationale,
        diff: iteration.diff,
        decisions: session.decisions,
        activeChange: session.activeChange,
      }
    } else if (ai.state.status === 'error') {
      cardView = { kind: 'error', title, message: ai.state.message }
    } else {
      cardView = { kind: 'loading', title, label: session.label }
    }
  }

  return {
    cardView,
    askAboutSelection,
    review: { acceptAll, applyDecided, rejectAll, close, decide, selectChange, stepChange },
  }
}

import type { ChangeDecision, ChangeSegment, SuggestionDiff } from '../../lib/diff'
import styles from './DiffView.module.css'

interface DiffViewProps {
  diff: SuggestionDiff
  decisions: ReadonlyMap<number, ChangeDecision>
  activeChange: number
  onSelectChange: (id: number) => void
}

/** A change that's only whitespace would be invisible, so it gets a mark. */
function visible(text: string): string {
  if (text === '' || text.trim() !== '') return text
  return text.includes('\n') ? '¶' : '␣'
}

function describe(change: ChangeSegment, position: number, decision: ChangeDecision | undefined): string {
  const action =
    change.removed === ''
      ? `add "${change.added}"`
      : change.added === ''
        ? `remove "${change.removed}"`
        : `replace "${change.removed}" with "${change.added}"`
  const state = decision === 'keep' ? ', kept' : decision === 'discard' ? ', discarded' : ''
  return `Change ${position + 1}: ${action}${state}`
}

function ChangeContent({ change, decision }: { change: ChangeSegment; decision: ChangeDecision | undefined }) {
  if (decision === 'keep') {
    return <ins className={styles.kept}>{visible(change.added) || '∅'}</ins>
  }
  if (decision === 'discard') {
    return <span className={styles.discarded}>{visible(change.removed) || '∅'}</span>
  }
  return (
    <>
      {change.removed !== '' && <del className={styles.removed}>{visible(change.removed)}</del>}
      {change.removed !== '' && change.added !== '' && ' '}
      {change.added !== '' && <ins className={styles.added}>{visible(change.added)}</ins>}
    </>
  )
}

export function DiffView({ diff, decisions, activeChange, onSelectChange }: DiffViewProps) {
  if (diff.mode === 'block') {
    const change = diff.segments[0]
    if (change?.kind !== 'change') return null
    return (
      <div className={styles.block}>
        <p className={styles.blockLabel}>Before</p>
        <p className={styles.text}>
          <del className={styles.removed}>{change.removed}</del>
        </p>
        <p className={styles.blockLabel}>After</p>
        <p className={styles.text}>
          <ins className={styles.added}>{change.added}</ins>
        </p>
      </div>
    )
  }

  let position = -1
  return (
    <p className={styles.text}>
      {diff.segments.map((segment, index) => {
        if (segment.kind === 'same') return <span key={index}>{segment.text}</span>
        position += 1
        const decision = decisions.get(segment.id)
        const active = segment.id === activeChange
        // The row below the diff is the keyboard path, with 44px targets, so
        // these stay out of the tab order: a long diff would be dozens of stops.
        return (
          <button
            key={index}
            type="button"
            tabIndex={-1}
            className={active ? styles.changeActive : styles.change}
            aria-pressed={active}
            aria-label={describe(segment, position, decision)}
            onClick={() => onSelectChange(segment.id)}
          >
            <ChangeContent change={segment} decision={decision} />
          </button>
        )
      })}
    </p>
  )
}

