import type { Editor } from '@tiptap/core'
import styles from './App.module.css'
import { CoAuthorCard } from './components/CoAuthorCard/CoAuthorCard'
import { EditorPane } from './components/EditorPane/EditorPane'
import { SelectionPill } from './components/SelectionPill/SelectionPill'
import { Sidebar } from './components/Sidebar/Sidebar'
import { Toast } from './components/Toast/Toast'
import {
  APP_NAME,
  DOCUMENT_FILE_NAME,
  DOCUMENT_SUBTITLE,
  DOCUMENT_TITLE,
  PILL_COMMANDS,
  TONE_COMMANDS,
} from './constants'
import type { Command } from './constants'
import { useBlazeEditor } from './hooks/useBlazeEditor'
import { useNotice } from './hooks/useNotice'
import { useSelectionPill } from './hooks/useSelectionPill'
import { askCommand, useSuggestion } from './hooks/useSuggestion'

function Workspace({ editor }: { editor: Editor }) {
  const { notice, show: showNotice, dismiss: dismissNotice } = useNotice()
  const suggestion = useSuggestion(editor, showNotice)
  const pill = useSelectionPill(editor)

  const runCommand = (command: Command) => {
    suggestion.askAboutSelection(command)
    pill.close()
  }

  const undo = () => {
    editor.commands.undo()
    dismissNotice()
  }

  return (
    <div className={styles.app}>
      <Sidebar appName={APP_NAME} documentTitle={DOCUMENT_TITLE} documentSubtitle={DOCUMENT_SUBTITLE} />
      <EditorPane editor={editor} fileName={DOCUMENT_FILE_NAME} />
      <CoAuthorCard view={suggestion.cardView} actions={suggestion.review} />
      {pill.position && (
        <SelectionPill
          appName={APP_NAME}
          position={pill.position}
          view={pill.view}
          commands={PILL_COMMANDS}
          toneCommands={TONE_COMMANDS}
          askText={pill.askText}
          onViewChange={pill.setView}
          onAskTextChange={pill.setAskText}
          onCommand={runCommand}
          onAsk={() => runCommand(askCommand(pill.askText))}
        />
      )}
      <Toast notice={notice} onUndo={undo} />
    </div>
  )
}

export default function App() {
  const editor = useBlazeEditor()
  return <Workspace editor={editor} />
}

import { open, select, docText, cardText, waitReview, SHOTS } from './lib.mjs'

const { browser, page, problems } = await open()
const original = await docText(page)
const check = (name, ok) => console.log((ok ? 'PASS ' : 'FAIL ') + name)

// Partial accept
await select(page, 'Right now the support team basically spends most of their day answering the same questions over and over again')
await page.getByRole('button', { name: 'Shorter' }).click()
await waitReview(page)
await page.screenshot({ path: SHOTS + 'accept-1-review.png' })
console.log(await cardText(page))
const row = page.getByRole('group', { name: /Review one change/ })
const keep = row.getByRole('button', { name: 'Keep' })
const discard = row.getByRole('button', { name: 'Discard' })
if (await row.isVisible()) {
  await keep.click()
  await page.waitForTimeout(100)
  await page.screenshot({ path: SHOTS + 'accept-2-decided.png' })
  const heights = await page.evaluate(() => [...document.querySelectorAll('aside[aria-label="Co-author"] button')].filter((b) => b.tabIndex !== -1).map((b) => [b.innerText || b.getAttribute('aria-label'), Math.round(b.getBoundingClientRect().height)]))
  console.log('targets:', JSON.stringify(heights))
  check('every card control is at least 44px', heights.every(([, h]) => h >= 44))
  await page.getByRole('button', { name: /^Apply/ }).click()
  await page.waitForTimeout(150)
  const after = await docText(page)
  check('partial accept changed the document', after !== original)
  check('toast offers Undo', await page.getByRole('button', { name: 'Undo' }).isVisible())
  await page.screenshot({ path: SHOTS + 'accept-3-applied.png' })
  await page.keyboard.press('Control+z')
  await page.waitForTimeout(150)
  check('one Ctrl+Z restores the document', (await docText(page)) === original)
}

// Edit while pending: discard with a notice
await select(page, 'We are going to log every suggestion')
await page.getByRole('button', { name: 'Rewrite' }).click()
await waitReview(page)
await page.evaluate(() => {
  const p = [...document.querySelectorAll('.tiptap p')].find((e) => e.innerText.startsWith('Every answer'))
  const r = document.createRange(); r.setStart(p.firstChild, 0); r.collapse(true)
  const s = getSelection(); s.removeAllRanges(); s.addRange(r); document.querySelector('.tiptap').focus()
})
await page.keyboard.type('X')
await page.waitForTimeout(200)
check('editing the paragraph shows the notice', await page.getByText(/You edited this text/).isVisible())
check('the card went back to idle', (await cardText(page)).includes('Nothing to review'))
await page.screenshot({ path: SHOTS + 'accept-4-discarded.png' })
await page.keyboard.press('Control+z')
await page.waitForTimeout(150)

// Reject leaves the text alone; accept all then undo
await select(page, "We'll know it's working")
await page.getByRole('button', { name: 'Fix grammar' }).click()
await waitReview(page).catch(() => {})
await page.getByRole('button', { name: /Reject all|Close/ }).click()
await page.waitForTimeout(100)
check('reject leaves the document as it was', (await docText(page)) === original)

console.log('problems:', JSON.stringify(problems))
await browser.close()
process.exit(0)

