import type { FormEvent } from 'react'
import type { Command } from '../../constants'
import styles from './RefineControls.module.css'

interface RefineControlsProps {
  appName: string
  commands: Command[]
  text: string
  disabled: boolean
  onTextChange: (text: string) => void
  onCommand: (command: Command) => void
  onSubmitText: () => void
}

export function RefineControls({
  appName,
  commands,
  text,
  disabled,
  onTextChange,
  onCommand,
  onSubmitText,
}: RefineControlsProps) {
  const submit = (event: FormEvent) => {
    event.preventDefault()
    if (!disabled && text.trim() !== '') onSubmitText()
  }

  return (
    <div className={styles.refine}>
      <h3 className={styles.label}>Refine this suggestion</h3>
      <div className={styles.chips}>
        {commands.map((command) => (
          <button
            key={command.id}
            className={styles.chip}
            type="button"
            disabled={disabled}
            onClick={() => onCommand(command)}
          >
            <span className={styles.dot} aria-hidden="true" />
            {command.label}
          </button>
        ))}
      </div>
      <form className={styles.form} onSubmit={submit}>
        <label className="visually-hidden" htmlFor="refine-text">
          Tell {appName} what to change
        </label>
        <input
          id="refine-text"
          className={styles.input}
          value={text}
          onChange={(event) => onTextChange(event.target.value)}
          placeholder={`Or tell ${appName} what to change…`}
          autoComplete="off"
        />
        <button className={styles.send} type="submit" aria-label="Send" disabled={disabled || text.trim() === ''}>
          <span aria-hidden="true">↵</span>
        </button>
      </form>
    </div>
  )
}

.refine {
  margin-top: var(--space-6);
  padding-top: var(--space-5);
  border-top: 1px solid var(--color-on-dark-hairline);
}

.label {
  color: var(--color-on-dark-muted);
  font-family: var(--font-mono);
  font-size: var(--text-micro);
  font-weight: 400;
  letter-spacing: 0.04em;
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: var(--space-3);
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  min-height: var(--size-target);
  padding: 0 var(--space-4);
  border: 1px solid var(--color-on-dark-border);
  border-radius: var(--radius-pill);
  background: none;
  color: var(--color-on-dark);
  font-size: var(--text-sm);
}

.chip:hover:not(:disabled) {
  background: var(--color-on-dark-hover);
}

.chip:disabled,
.send:disabled {
  opacity: 0.55;
}

.dot {
  flex: none;
