import { open, docText, cardText, waitReview, SHOTS } from './lib.mjs'

const { browser, page, problems } = await open()
const original = await docText(page)
const check = (name, ok) => console.log((ok ? 'PASS ' : 'FAIL ') + name)
const sent = []
page.on('request', (r) => { if (r.url().includes('/api/suggest')) sent.push(JSON.parse(r.postData())) })

await page.screenshot({ path: SHOTS + 'first-1-open.png' })
check('the hint is showing', await page.getByText('Select any sentence to ask for a rewrite').isVisible())
const prompts = page.getByRole('button', { name: /Make / })
check('three Try one prompts', (await prompts.count()) === 3)
const heights = await prompts.evaluateAll((els) => els.map((e) => Math.round(e.getBoundingClientRect().height)))
check('prompts are at least 44px: ' + heights, heights.every((h) => h >= 44))

// One click, no reading: the measurable prompt on the sample document.
await page.getByRole('button', { name: 'Make the success metric measurable' }).click()
await page.waitForTimeout(100)
check('the hint goes away after the first ask', !(await page.getByText('Select any sentence to ask for a rewrite').isVisible()))
await waitReview(page)
await page.screenshot({ path: SHOTS + 'first-2-review.png' })
console.log(await cardText(page))
check('it asks about a section', sent[0].target === 'section')
check('it sends only that section', sent[0].selection === "We'll know it's working when tickets get answered faster.")
check('the document is unchanged', (await docText(page)) === original)
await page.getByRole('button', { name: /Reject all|Close/ }).click()

// Deleting a section's heading removes its prompt.
await page.evaluate(() => {
  const h = [...document.querySelectorAll('.tiptap h2')].find((e) => e.innerText === 'Success metrics')
  const r = document.createRange(); r.selectNodeContents(h)
  const s = getSelection(); s.removeAllRanges(); s.addRange(r); document.querySelector('.tiptap').focus()
})
await page.waitForTimeout(100)
await page.keyboard.press('Backspace')
await page.waitForTimeout(200)
check('a prompt disappears when its section is gone', (await page.getByRole('button', { name: /Make / }).count()) === 2)

// Writing from scratch: the brief's "open it, write something" path.
await page.evaluate(() => {
  const last = document.querySelector('.tiptap').lastElementChild
  const r = document.createRange(); r.selectNodeContents(last); r.collapse(false)
  const s = getSelection(); s.removeAllRanges(); s.addRange(r); document.querySelector('.tiptap').focus()
})
await page.keyboard.press('Enter')
await page.keyboard.type('i think this sentance i just wrote has a typo in it')
await page.waitForTimeout(100)
const line = page.locator('.tiptap p', { hasText: 'i just wrote' })
await line.click({ clickCount: 3 })
await page.waitForTimeout(200)
await page.getByRole('button', { name: 'Fix grammar' }).click()
await waitReview(page)
console.log(await cardText(page))
check('a suggestion works on text just typed', sent.at(-1).selection.includes('i just wrote'))
await page.getByRole('button', { name: 'Accept all' }).click()
await page.waitForTimeout(200)
check('accepting it changes the typed text', !(await docText(page)).includes('sentance'))
await page.screenshot({ path: SHOTS + 'first-3-typed.png' })

console.log('problems:', JSON.stringify(problems))
await Promise.race([browser.close(), new Promise((r) => setTimeout(r, 3000))])
process.exit(0)

