      dispatch({
        type: 'addIteration',
        iteration: makeIteration(target.markdown, command.label, rewrite, suggestion.rationale),
      })
      setRefineText('')
    },
    [editor, run],
  )

  const askAbout = useCallback(
    (target: SuggestionPlace, command: Command) => {
      setHasAsked(true)
