import type { Editor } from '@tiptap/core'
import { useCallback, useState } from 'react'
import { placeForPalette } from '../lib/editorDocument'
import type { SuggestionPlace } from '../lib/editorDocument'
import { movePaletteIndex } from '../lib/keyboard'

interface PaletteState {
  /** What a command would act on, fixed when the palette opens. */
  place: SuggestionPlace | null
  /** True during a review: commands refine it rather than start a new one. */
  refining: boolean
  index: number
  askText: string
}

export function usePalette(editor: Editor, total: number, reviewingPlace: SuggestionPlace | null) {
  const [state, setState] = useState<PaletteState | null>(null)

  const open = useCallback(() => {
    setState({
      place: reviewingPlace ?? placeForPalette(editor),
      refining: reviewingPlace !== null,
      index: 0,
      askText: '',
    })
  }, [editor, reviewingPlace])

  const close = useCallback(() => setState(null), [])

  const moveWithKey = useCallback(
    (key: string) => {
      setState((current) => current && { ...current, index: movePaletteIndex(current.index, total, key) })
    },
    [total],
  )

  const setIndex = useCallback((index: number) => {
    setState((current) => current && { ...current, index })
  }, [])

  const setAskText = useCallback((askText: string) => {
    setState((current) => current && { ...current, askText })
  }, [])

  return { state, open, close, moveWithKey, setIndex, setAskText }
}

import type { Editor } from '@tiptap/core'
import { useEffect } from 'react'
import { keyAction } from '../lib/keyboard'
import type { KeyAction, KeyContext } from '../lib/keyboard'

interface ShortcutOptions {
  overlayOpen: boolean
  reviewing: boolean
  onAction: (action: Exclude<KeyAction, null>) => void
}

function focusOf(editor: Editor): KeyContext['focus'] {
  const active = document.activeElement
  if (active instanceof HTMLInputElement || active instanceof HTMLTextAreaElement) return 'input'
  return active && editor.view.dom.contains(active) ? 'editor' : 'other'
}

/** Listens before the editor does, so a slash that opens the palette isn't typed. */
export function useShortcuts(editor: Editor, { overlayOpen, reviewing, onAction }: ShortcutOptions) {
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      const { selection } = editor.state
      const action = keyAction({
        key: event.key,
        mod: event.ctrlKey || event.metaKey,
        focus: focusOf(editor),
        selectionEmpty: selection.empty,
        onEmptyLine: selection.empty && selection.$from.parent.content.size === 0,
        overlayOpen,
        reviewing,
      })
      if (!action) return
      event.preventDefault()
      event.stopPropagation()
      onAction(action)
    }

    window.addEventListener('keydown', onKeyDown, true)
    return () => window.removeEventListener('keydown', onKeyDown, true)
  }, [editor, onAction, overlayOpen, reviewing])
}

import type { FormEvent, KeyboardEvent } from 'react'
import type { Command } from '../../constants'
import styles from './CommandPalette.module.css'

interface CommandPaletteProps {
  appName: string
  /** What a command would act on, or null if there's nothing to act on. */
  targetTitle: string | null
  commands: Command[]
  index: number
  askText: string
  onAskTextChange: (text: string) => void
  onMove: (key: string) => void
  onHover: (index: number) => void
  onRun: (command: Command) => void
  onAsk: () => void
  onClose: () => void
}

export function CommandPalette({
  appName,
  targetTitle,
  commands,
  index,
  askText,
  onAskTextChange,
  onMove,
  onHover,
  onRun,
  onAsk,
  onClose,
}: CommandPaletteProps) {
  const available = targetTitle !== null

  const onKeyDown = (event: KeyboardEvent) => {
    if (event.key === 'Escape') {
      event.preventDefault()
      onClose()
    } else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      onMove(event.key)
    } else if (event.key === 'Tab') {
      // The field drives the list, so focus stays inside the palette.
      event.preventDefault()
    }
  }

  const submit = (event: FormEvent) => {
    event.preventDefault()
    if (!available) return
    if (askText.trim() !== '') {
      onAsk()
      return
    }
    const command = commands[index]
    if (command) onRun(command)
  }

  return (
    <div
      className={styles.palette}
      role="dialog"
      aria-modal="true"
      aria-label="Commands"
      onClick={(event) => {
        if (event.target === event.currentTarget) onClose()
      }}
      onKeyDown={onKeyDown}
    >
      <div className={styles.box}>
        <div className={styles.top}>
          <span>
            / commands ·{' '}
            {available ? `on “${targetTitle}”` : 'select text, or put the cursor in a section with text'}
          </span>
          <span className={styles.keys}>↑ ↓ to move · ↵ to run · esc to close</span>
          <button className={styles.close} type="button" tabIndex={-1} onClick={onClose}>
            Close
          </button>
        </div>

        <form onSubmit={submit}>
          <label className="visually-hidden" htmlFor="palette-ask">
            Ask {appName} something else
          </label>
          <input
            id="palette-ask"
            className={styles.input}
            value={askText}
            onChange={(event) => onAskTextChange(event.target.value)}
            placeholder={`Or ask ${appName} to…`}
            autoComplete="off"
            autoFocus
            disabled={!available}
            role="combobox"
            aria-expanded="true"
            aria-controls="palette-commands"
            aria-activedescendant={available ? `palette-command-${index}` : undefined}
          />
        </form>

        <div id="palette-commands" className={styles.list} role="listbox" aria-label="Commands">
          {commands.map((command, position) => (
            <button
              key={command.id}
              id={`palette-command-${position}`}
              className={position === index && available ? styles.itemActive : styles.item}
              type="button"
              role="option"
              tabIndex={-1}
              aria-selected={position === index}
              disabled={!available}
              onMouseMove={() => onHover(position)}
              onClick={() => onRun(command)}
            >
              <span className={styles.dot} aria-hidden="true" />
              {command.label}
              {position === index && available && (
                <span className={styles.enter} aria-hidden="true">
                  ↵
                </span>
              )}
            </button>
          ))}
        </div>
      </div>
    </div>
  )
}

.palette {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-7);
  background:
    var(--noise),
    linear-gradient(160deg, var(--color-palette-backdrop-start) 40%, var(--color-palette-backdrop-end) 140%);
  background-size: 200px 200px, auto;
  color: var(--color-on-dark);
}

.box {
  width: min(760px, 100%);
}

.top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
  color: var(--color-on-dark-muted);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  letter-spacing: 0.04em;
}

.keys {
