  min-width: var(--size-target);
  min-height: var(--size-target);
  padding: 0 var(--space-4);
  border: 1px solid var(--color-on-dark-border);
  border-radius: var(--radius-pill);
  background: none;
  color: var(--color-on-dark);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
}

.input {
  width: 100%;
  min-height: var(--size-target);
  margin: var(--space-4) 0 var(--space-6);
  padding: 0 var(--space-5);
  border: 1px solid var(--color-on-dark-border);
  border-radius: var(--radius-pill);
  outline: none;
  background: var(--color-on-dark-fill);
  color: var(--color-on-dark);
  font-size: var(--text-lg);
}

.input::placeholder {
  color: var(--color-on-dark-placeholder);
}

.input:focus {
  border-color: var(--color-on-dark);
}

.list {
  display: flex;
  flex-direction: column;
}

.item,
.itemActive {
  display: flex;
  align-items: center;
  gap: var(--space-6);
  width: 100%;
  border: 0;
  background: none;
  font-size: var(--text-palette);
  letter-spacing: -0.045em;
  line-height: 1.12;
  text-align: left;
}

.item {
  color: var(--color-palette-idle);
  font-weight: 300;
}

.itemActive {
  color: var(--color-on-dark);
  font-weight: 500;
}

.dot {
  flex: none;
  width: 10px;
  height: 10px;
  border: 1.5px solid currentColor;
  border-radius: 50%;
  opacity: 0;
}

.itemActive .dot {
  opacity: 1;
}

.enter {
  margin-left: auto;
  color: var(--color-on-dark-muted);
  font-family: var(--font-mono);
  font-size: var(--text-md);
  font-weight: 400;
  letter-spacing: 0;
}

import type { ShortcutRow } from '../../constants'
import styles from './ShortcutList.module.css'

interface ShortcutListProps {
  rows: ShortcutRow[]
}

export function ShortcutList({ rows }: ShortcutListProps) {
  return (
    <dl className={styles.list}>
      {rows.map((row) => (
        <div key={row.keys} className={styles.row}>
          <dt>
            <kbd className={styles.key}>{row.keys}</kbd>
          </dt>
          <dd>{row.description}</dd>
        </div>
      ))}
    </dl>
  )
}

.list {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: var(--space-3) var(--space-5);
  margin-top: var(--space-3);
  font-size: var(--text-md);
}

.row {
  display: contents;
}

.key {
  display: inline-block;
  padding: 1px var(--space-2);
  border: 1px solid var(--color-line-strong);
  border-radius: var(--radius-xs);
  background: var(--color-sheet);
  color: var(--color-ink);
  font-family: var(--font-mono);
  font-size: var(--text-micro);
  font-weight: 500;
}

import type { KeyboardEvent } from 'react'
import type { ShortcutRow } from '../../constants'
import { ShortcutList } from '../ShortcutList/ShortcutList'
import styles from './ShortcutsDialog.module.css'

interface ShortcutsDialogProps {
  rows: ShortcutRow[]
  onClose: () => void
}

export function ShortcutsDialog({ rows, onClose }: ShortcutsDialogProps) {
  const onKeyDown = (event: KeyboardEvent) => {
    if (event.key === 'Escape') {
      event.preventDefault()
      onClose()
    } else if (event.key === 'Tab') {
      // "Got it" is the only control, so focus stays on it.
      event.preventDefault()
    }
  }

  return (
    <div
      className={styles.scrim}
      onClick={(event) => {
        if (event.target === event.currentTarget) onClose()
      }}
      onKeyDown={onKeyDown}
    >
      <div className={styles.dialog} role="dialog" aria-modal="true" aria-labelledby="shortcuts-title">
        <p className={styles.label}>Keyboard</p>
        <h2 id="shortcuts-title" className={styles.title}>
          Shortcuts
        </h2>
        <ShortcutList rows={rows} />
        <button className={styles.done} type="button" onClick={onClose} autoFocus>
          Got it
        </button>
      </div>
    </div>
  )
}

.scrim {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  padding: var(--space-7);
  background: var(--color-scrim);
}

