.sheet :global(.tiptap) {
  outline: none;
  counter-reset: section;
}

.sheet :global(.tiptap) ::selection {
  background: var(--color-selection);
}

.sheet :global(.tiptap h1) {
  margin-bottom: var(--space-3);
  font-size: var(--text-h1);
  font-weight: 600;
  letter-spacing: -0.04em;
