const { browser, page } = await open()
const st = async (l) => console.log(l, await page.evaluate(() => ({ pill: !!document.querySelector('[role=toolbar]'), sel: getSelection().toString().slice(0, 24), active: document.activeElement?.className?.slice?.(0, 24) })))
await page.evaluate(() => {
  window.__log = []
  window.addEventListener('keydown', (e) => window.__log.push('keydown ' + e.key + ' prevented=' + e.defaultPrevented), false)
  document.addEventListener('selectionchange', () => window.__log.push('selectionchange:' + getSelection().toString().length))
})

