await page.keyboard.press('Escape'); await page.waitForTimeout(50); await st('A esc +50ms')
await page.waitForTimeout(300); await st('A esc +350ms')
console.log(JSON.stringify(await page.evaluate(() => window.__log.splice(0))))

// B: a real mouse selection, Esc.
await page.locator('.tiptap p', { hasText: 'Right now' }).click({ clickCount: 3 })
await page.waitForTimeout(200); await st('B triple click')
await page.keyboard.press('Escape'); await page.waitForTimeout(300); await st('B esc')
console.log(JSON.stringify(await page.evaluate(() => window.__log.splice(0))))
await Promise.race([browser.close(), new Promise((r) => setTimeout(r, 3000))])
process.exit(0)

