$utf8 = New-Object Text.UTF8Encoding $false
$scratch = "C:\Users\10021\AppData\Local\Temp\claude\19c04b2ae865ae71\95b23284-331e-4818-a4b1-00776a5bf5e6\scratchpad"
$repo = $PWD.Path

Write-Output '=== README: wording checks ==='
$bad = git grep --no-index -n -i -E "chiri|not an agent|non-agent|oxlint" -- README.md NOTES.md CLAUDE.md
if ($bad) { $bad; Write-Output 'WORDING CHECK FAILED'; exit 1 }
Write-Output 'no company name, no denial of being an agent, no leftover template text'

Write-Output '=== README: following its run steps in a fresh clone ==='
$clone = "$scratch\readme-check"
if (Test-Path -LiteralPath $clone) { Remove-Item -LiteralPath $clone -Recurse -Force -Confirm:$false }
git clone -q . $clone 2>$null
# The clone doesn't have the new README yet, so the steps are what's being checked, not its text.
Set-Location -LiteralPath $clone
pnpm install --frozen-lockfile 2>&1 | Select-Object -Last 1
Copy-Item -LiteralPath .env.example -Destination .env
$log = "$clone\dev.log"
$p = Start-Process -FilePath 'cmd.exe' -ArgumentList '/c', "pnpm dev > `"$log`" 2>&1" -PassThru -WindowStyle Hidden
try {
  $url = $null
  foreach ($i in 1..60) {
    if (Test-Path $log) {
      $m = Select-String -Path $log -Pattern 'Local:\s+(http://\S+)' | Select-Object -First 1
      if ($m -and (Select-String -Path $log -Pattern 'listening on' -Quiet)) { $url = $m.Matches[0].Groups[1].Value; break }
    }
    Start-Sleep -Milliseconds 500
  }
  Write-Output "pnpm dev printed: $url"
  if (-not $url) { Get-Content -LiteralPath $log; Write-Output 'DEV CHECK FAILED'; exit 1 }
  $r = Invoke-WebRequest -UseBasicParsing -Uri $url -TimeoutSec 10
  Write-Output "the printed URL answered: $($r.StatusCode)"
} finally {
  taskkill /PID $p.Id /T /F 2>$null | Out-Null
}
Set-Location -LiteralPath $repo

Write-Output '=== matrix ==='
$n = [IO.File]::ReadAllText("$repo\NOTES.md", $utf8)
foreach ($id in 'D2', 'E4', 'E5', 'S40') {
  $n = [regex]::Replace($n, "(?m)^(\| $id \|.*\| )planned( \|)$", '${1}done$2')
}
[IO.File]::WriteAllText("$repo\NOTES.md", $n, $utf8)
Select-String -Path NOTES.md -Pattern '\| (planned|manual) \|$' | ForEach-Object { $c = $_.Line -split '\|'; $c[1].Trim() + ' [' + $c[-2].Trim() + '] ' + $c[2].Trim().Substring(0, [Math]::Min(60, $c[2].Trim().Length)) }

Write-Output '=== checks ==='
& "$scratch\gates.ps1" 2>$null
if ($LASTEXITCODE -ne 0) { Write-Output 'NOT COMMITTING'; exit 1 }
git add -- NOTES.md README.md 2>$null
$s = git diff --cached --name-only
if ($s | Where-Object { $_ -match '(^|/)\.env' -and $_ -ne '.env.example' }) { Write-Output 'ABORT: .env staged'; exit 1 }
Write-Output ".env absent from staged list: $($s -join ', ')"
git commit -q -m "12: Write the README"
git log --oneline -4
Write-Output "ahead of any remote: $(git remote | Measure-Object -Line | Select-Object -ExpandProperty Lines) remotes configured"
git status --short
Write-Output '[status end]'

