import { chromium } from 'playwright-core'
const SHOTS = 'C:/Users/10021/AppData/Local/Temp/claude/19c04b2ae865ae71/95b23284-331e-4818-a4b1-00776a5bf5e6/scratchpad/e2e/'
const browser = await chromium.launch({ channel: 'msedge', headless: true })
for (const width of [375, 768, 1280, 1920]) {
  const page = await browser.newPage({ viewport: { width, height: 900 } })
  await page.route((u) => !['127.0.0.1', 'localhost'].includes(u.hostname), (r) => r.abort())
  await page.goto('http://127.0.0.1:5198/')
  await page.waitForSelector('.tiptap')
  const m = await page.evaluate(() => {
    const box = (s) => { const r = document.querySelector(s)?.getBoundingClientRect(); return r ? [Math.round(r.left), Math.round(r.right), Math.round(r.width)] : null }
    return { scrollW: document.documentElement.scrollWidth, sheet: box('article'), card: box('aside[aria-label="Co-author"]'), h1lines: Math.round(document.querySelector('.tiptap h1').getBoundingClientRect().height) }
  })
  console.log(width, JSON.stringify(m))
  await page.screenshot({ path: `${SHOTS}now-${width}.png` })
  await page.getByRole('button', { name: /Commands/ }).click({ timeout: 3000, force: true }).catch(() => console.log(width, 'Commands not clickable'))
  await page.waitForTimeout(200)
  const header = await page.locator('[role=dialog]').first().innerText().then((t) => t.split('\n')[0]).catch(() => 'no dialog')
  const disabled = await page.locator('[role=option]:disabled').count()
  console.log(width, 'palette header:', JSON.stringify(header), 'disabled options:', disabled)
  await page.screenshot({ path: `${SHOTS}now-${width}-palette.png` })
  await page.close()
}
await Promise.race([browser.close(), new Promise((r) => setTimeout(r, 3000))])
process.exit(0)

