 * from docs/design/mockup.html, except where it misses AA contrast or the 44px
 * target size. Those are marked "AA" or "44px", with the measured ratio.
 */
:root {
  /* Color: surfaces */
  --color-app: #f5f3f0;
  --color-sheet: #ffffff;
  --color-soft: #edeae6;
  --color-navy: #0f223a;
  --color-navy-light: #2f466f;
  --color-sky: #9ab3eb;

  /* Color: text on light surfaces */
  --color-ink: #0f223a;
  --color-body: #1f2a3d;
  --color-muted: #5f6672; /* AA: 5.22:1 on the app background, 5.78:1 on white */
  --color-gutter: var(--color-muted); /* AA: the mockup's #a8a39a is 2.51:1 on white */

  /* Color: text on the navy surfaces */
  --color-on-dark: #ffffff;
  --color-on-dark-soft: rgb(255 255 255 / 0.82);
  --color-on-dark-muted: rgb(255 255 255 / 0.7); /* AA: 5.61:1 at the lightest navy */
  --color-on-dark-placeholder: rgb(255 255 255 / 0.6);
  --color-on-dark-border: rgb(255 255 255 / 0.25);
  --color-on-dark-hairline: rgb(255 255 255 / 0.1);
  --color-on-dark-fill: rgb(255 255 255 / 0.07);
  --color-on-dark-hover: rgb(255 255 255 / 0.12);

  /* Color: diff on the navy card */
  --color-diff-removed: rgb(255 255 255 / 0.7); /* AA: the mockup's #8e8a7c is 2.73:1 here */
  --color-diff-added: #ffffff;
  --color-diff-added-fill: rgb(154 179 235 / 0.22);
  --color-diff-added-line: var(--color-sky);
  --color-diff-focus: #ffffff;

  /* Color: palette and overlays */
  --color-palette-idle: rgb(255 255 255 / 0.42); /* AA: the mockup's 0.28 is 2.50:1 */
  --color-palette-backdrop-start: rgb(15 34 58 / 0.97);
  --color-palette-backdrop-end: rgb(47 70 111 / 0.97);
  --color-scrim: rgb(24 26 77 / 0.35);

  /* Color: details on light surfaces */
  --color-line: rgb(24 26 77 / 0.08);
  --color-line-strong: rgb(24 26 77 / 0.18);
  --color-selection: rgb(154 179 235 / 0.55);
  --color-target-fill: rgb(154 179 235 / 0.28);
  --color-shadow-soft: rgb(24 26 77 / 0.06);
  --color-shadow: rgb(24 26 77 / 0.25);
  --color-shadow-strong: rgb(24 26 77 / 0.3);

  /* Fonts */
  --font-sans: 'Inter Tight', system-ui, sans-serif;
  --font-mono: 'IBM Plex Mono', ui-monospace, monospace;
  --font-wide: 'Archivo', sans-serif;

  /* Font sizes */
  --text-micro: 11px;
  --text-xs: 12px;
  --text-sm: 13px;
  --text-md: 14px;
  --text-lg: 15px;
  --text-body: 18px;
