input.content:
.app {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  background: var(--color-app);
}

/* The document and the card stay together: stacked here, side by side from 1024px. */
.workspace {
  display: grid;
  grid-template-columns: minmax(0, var(--size-sheet));
  justify-content: center;
  column-gap: var(--space-workspace-gap);
  min-width: 0;
  padding-inline: var(--space-workspace-x);
}

@media (min-width: 1024px) {
  .app {
    display: grid;
    grid-template-columns: var(--size-sidebar) minmax(0, 1fr);
  }

  .workspace {
    grid-template-columns: minmax(0, var(--size-sheet)) var(--size-panel);
  }
}

/* A sticky bar on top, under 1024px. */
.sidebar {
  position: sticky;
  top: 0;
  z-index: 15;
  display: flex;
  align-items: center;
  gap: var(--space-3);
  min-height: var(--size-app-bar);
  padding: var(--space-3) var(--space-4);
  background: var(--surface-navy);
  background-size: 200px 200px, auto;
  color: var(--color-on-dark);
}

.logo {
  font-family: var(--font-wide);
  font-size: var(--text-title);
  font-stretch: 125%;
  font-variation-settings: 'wdth' 125;
  font-weight: 900;
  letter-spacing: -0.01em;
  line-height: 1;
  text-transform: uppercase;
}

.label,
.document {
  display: none;
}

.subtitle {
  display: block;
  margin-top: var(--space-1);
  color: var(--color-on-dark-muted);
  font-family: var(--font-mono);
  font-size: var(--text-micro);
}

.buttons {
  display: flex;
  gap: var(--space-2);
  margin-left: auto;
}

.button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  min-height: var(--size-target);
  padding: 0 var(--space-4);
  border: 1px solid var(--color-on-dark-border);
  border-radius: var(--radius-sm);
  background: none;
  color: var(--color-on-dark);
  font-size: var(--text-md);
  font-weight: 500;
}

.button:hover {
  background: var(--color-on-dark-hover);
}

/* Phones have no / or ? key to press. */
.key {
  display: none;
  color: var(--color-on-dark-muted);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
}

@media (min-width: 640px) {
  .key {
    display: inline;
  }
}

@media (min-width: 1024px) {
  .sidebar {
    flex-direction: column;
    align-items: stretch;
    gap: var(--space-2);
    height: 100vh;
    padding: var(--space-7) var(--space-6);
  }

  .logo {
    margin: var(--space-3) 0 var(--space-9);
    font-size: var(--text-card-title);
  }

  .label {
    display: block;
    margin-bottom: var(--space-2);
    color: var(--color-on-dark-muted);
    font-family: var(--font-mono);
    font-size: var(--text-micro);
    font-weight: 400;
    letter-spacing: 0.04em;
  }

  .document {
    display: block;
    padding: var(--space-4);
    border-radius: var(--radius-sm);
    background: var(--color-on-dark-hairline);
    font-size: var(--text-lg);
    line-height: 1.3;
  }

  .buttons {
    flex-direction: column;
    margin-top: auto;
    margin-left: 0;
  }
}

