input.content:
.toast {
  position: fixed;
  right: var(--space-3);
  bottom: var(--space-4);
  left: var(--space-3);
  z-index: 70;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  min-height: var(--size-target);
  padding: var(--space-1) var(--space-5);
  border-radius: var(--radius-lg);
  background: var(--surface-navy);
  background-size: 200px 200px, auto;
  box-shadow: 0 10px 30px var(--color-shadow);
  color: var(--color-on-dark);
  font-size: var(--text-md);
}

@media (min-width: 640px) {
  .toast {
    right: auto;
    bottom: var(--space-8);
    left: 50%;
    padding: 0 var(--space-6);
    border-radius: var(--radius-pill);
    transform: translateX(-50%);
  }
}

.hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}

.undo {
  flex: none;
  min-width: var(--size-target);
  min-height: var(--size-target);
  border: 0;
  background: none;
  color: var(--color-sky);
  font-size: var(--text-md);
  font-weight: 600;
}

/* Spans the screen and wraps on narrow screens, and floats over the selection from 640px. */
.pill {
  position: fixed;
  top: var(--pill-top);
  right: var(--space-3);
  left: var(--space-3);
  z-index: 30;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 2px;
  padding: var(--space-1);
  border-radius: var(--radius-lg);
  background: var(--surface-navy);
  background-size: 200px 200px, auto;
  box-shadow: 0 12px 34px var(--color-shadow-strong);
  transform: translateY(calc(-100% - var(--space-3)));
}

.below {
  transform: translateY(var(--space-3));
}

@media (min-width: 640px) {
  .pill {
    right: auto;
    left: var(--pill-left);
    flex-wrap: nowrap;
    border-radius: var(--radius-pill);
    transform: translate(-50%, calc(-100% - var(--space-3)));
  }

  .below {
    transform: translate(-50%, var(--space-3));
  }
}

.button {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  min-width: var(--size-target);
  min-height: var(--size-target);
  justify-content: center;
  padding: 0 var(--space-4);
  border: 0;
  border-radius: var(--radius-pill);
  background: none;
  color: var(--color-on-dark);
