import { openApp, SAFE_SENTENCE, selectText, test } from './support.ts'

test('where is the pill at 375', async ({ page }) => {
  await page.setViewportSize({ width: 375, height: 800 })
  await openApp(page)
  await selectText(page, SAFE_SENTENCE)
  const report = await page.evaluate(() => {
    const box = document.querySelector('[role=toolbar]')?.getBoundingClientRect()
    const range = getSelection()?.getRangeAt(0).getBoundingClientRect()
    return {
      viewportHeight: innerHeight,
      scrollY,
      selectionTop: range && Math.round(range.top),
      selectionBottom: range && Math.round(range.bottom),
      pillTop: box && Math.round(box.top),
      pillBottom: box && Math.round(box.bottom),
    }
  })
  console.log('REPORT ' + JSON.stringify(report))
})

