import { chromium } from 'playwright-core'
const OUT = 'C:/Users/10021/AppData/Local/Temp/claude/19c04b2ae865ae71/95b23284-331e-4818-a4b1-00776a5bf5e6/scratchpad/screens/'
const URL_ = 'http://127.0.0.1:5198/'
const REWRITE = 'We will log all suggestions and whether it was accepted'
const SENTENCE = 'We are going to log every suggestion and whether it was accepted'
const browser = await chromium.launch({ channel: 'msedge', headless: true })

async function select(page, text) {
  await page.evaluate((t) => {
    const w = document.createTreeWalker(document.querySelector('.tiptap'), NodeFilter.SHOW_TEXT)
    for (let n = w.nextNode(); n; n = w.nextNode()) {
      const i = n.textContent.indexOf(t)
      if (i >= 0) { const r = document.createRange(); r.setStart(n, i); r.setEnd(n, i + t.length); const s = getSelection(); s.removeAllRanges(); s.addRange(r); return }
    }
  }, text)
  await page.waitForTimeout(200)
}

for (const width of [375, 768, 1024, 1280, 1920]) {
  const page = await browser.newPage({ viewport: { width, height: width < 1024 ? 812 : 900 } })
  const replies = []
  // Fonts stay reachable here so the screenshots show the real type. The API is stubbed.
  await page.route('**/api/suggest', async (route) => {
    const next = replies.shift()
    if (next === 'hang') return
    await route.fulfill({ json: next })
  })
  await page.goto(URL_)
  await page.waitForSelector('.tiptap', { state: 'attached' })
