.palette {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  overflow: auto;
  padding: var(--space-5);
  background:
    var(--noise),
    linear-gradient(160deg, var(--color-palette-backdrop-start) 40%, var(--color-palette-backdrop-end) 140%);
  background-size: 200px 200px, auto;
  color: var(--color-on-dark);
}

/* An auto margin centers it, and unlike centering it can still scroll when tall. */
.box {
  width: min(760px, 100%);
  margin: auto;
}

.top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2) var(--space-5);
  color: var(--color-on-dark-muted);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  letter-spacing: 0.04em;
}

/* Full width on narrow screens, so the header never becomes a thin column. */
.target {
  flex: 1 1 100%;
  min-width: 0;
}

/* Phones have no arrow or Esc keys to press. */
.keys {
  display: none;
  white-space: nowrap;
}

@media (min-width: 640px) {
  .top {
    flex-wrap: nowrap;
  }

  .target {
    flex-basis: 0;
  }

  .keys {
    display: inline;
  }
}

.close {
  flex: none;
  margin-left: auto;
  min-width: var(--size-target);
  min-height: var(--size-target);
  padding: 0 var(--space-4);
  border: 1px solid var(--color-on-dark-border);
  border-radius: var(--radius-pill);
  background: none;
  color: var(--color-on-dark);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
}

.nothing {
  margin-top: var(--space-6);
  font-size: var(--text-palette);
  font-weight: 300;
  letter-spacing: -0.045em;
  line-height: 1.12;
}

.input {
  width: 100%;
  min-height: var(--size-target);
  margin: var(--space-4) 0 var(--space-6);
  padding: 0 var(--space-5);
  border: 1px solid var(--color-on-dark-border);
  border-radius: var(--radius-pill);
  outline: none;
  background: var(--color-on-dark-fill);
  color: var(--color-on-dark);
  font-size: var(--text-lg);
}

.input::placeholder {
  color: var(--color-on-dark-placeholder);
}

.input:focus {
  border-color: var(--color-on-dark);
}

.list {
  display: flex;
  flex-direction: column;
}

.item,
.itemActive {
  display: flex;
  align-items: center;
  gap: var(--space-6);
  width: 100%;
  border: 0;
  background: none;
  font-size: var(--text-palette);
  letter-spacing: -0.045em;
  line-height: 1.12;
  text-align: left;
}

.item {
  color: var(--color-palette-idle);
  font-weight: 300;
}

.itemActive {
  color: var(--color-on-dark);
  font-weight: 500;
}

.dot {
  flex: none;
  width: 10px;
  height: 10px;
  border: 1.5px solid currentColor;
  border-radius: 50%;
  opacity: 0;
}

.itemActive .dot {
  opacity: 1;
}

.enter {
  margin-left: auto;
  color: var(--color-on-dark-muted);
  font-family: var(--font-mono);
  font-size: var(--text-md);
  font-weight: 400;
  letter-spacing: 0;
}

.text {
  color: var(--color-on-dark-soft);
  font-size: var(--text-lg);
  line-height: 1.6;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.change,
.changeActive {
  display: inline;
  padding: 0;
  border: 0;
  border-radius: var(--radius-xs);
  background: none;
  color: inherit;
  font: inherit;
  line-height: inherit;
  text-align: left;
  white-space: pre-wrap;
}

.change:hover {
  background: var(--color-on-dark-hover);
}

.changeActive {
  outline: 2px solid var(--color-diff-focus);
  outline-offset: 2px;
}

/* Deleted and added text differ by more than color: strike and underline. */
.removed {
  color: var(--color-diff-removed);
  text-decoration: line-through;
}

.added {
  border-bottom: 2px solid var(--color-diff-added-line);
  background: var(--color-diff-added-fill);
  color: var(--color-diff-added);
  text-decoration: none;
}

.kept {
  border-bottom: 1px solid var(--color-diff-added-line);
  color: var(--color-diff-added);
  text-decoration: none;
}

.discarded {
  border-bottom: 1px dotted var(--color-on-dark-muted);
}

.mark {
