import { chromium } from 'playwright-core'
const OUT = 'C:/Users/10021/AppData/Local/Temp/claude/19c04b2ae865ae71/95b23284-331e-4818-a4b1-00776a5bf5e6/scratchpad/screens/'
const browser = await chromium.launch({ channel: 'msedge', headless: true })
const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 2 })
await page.route('**/api/suggest', (route) => route.fulfill({ json: { rewrite: 'We will log all suggestions and whether it was accepted', rationale: 'x' } }))
await page.goto('http://127.0.0.1:5198/')
await page.waitForSelector('.tiptap')
await page.waitForTimeout(500)
await page.evaluate(() => {
  const t = 'We are going to log every suggestion and whether it was accepted'
  const w = document.createTreeWalker(document.querySelector('.tiptap'), NodeFilter.SHOW_TEXT)
  for (let n = w.nextNode(); n; n = w.nextNode()) { const i = n.textContent.indexOf(t); if (i >= 0) { const r = document.createRange(); r.setStart(n, i); r.setEnd(n, i + t.length); const s = getSelection(); s.removeAllRanges(); s.addRange(r); return } }
})
await page.waitForTimeout(200)
await page.getByRole('toolbar').getByRole('button', { name: 'Shorter', exact: true }).click()
await page.getByRole('button', { name: 'Accept all' }).waitFor()
await page.waitForTimeout(200)
const box = await page.locator('aside[aria-label="Co-author"] p:has(del)').boundingBox()
await page.screenshot({ path: OUT + 'crop-diff.png', clip: { x: box.x - 4, y: box.y - 6, width: box.width + 8, height: Math.min(box.height + 12, 90) } })
await Promise.race([browser.close(), new Promise((r) => setTimeout(r, 3000))])
process.exit(0)

