// Takes the README screenshots with the API stubbed. Takes the output folder as an argument.
import { chromium } from 'playwright-core'
const OUT = process.argv[2]
const SENTENCE = 'We are going to log every suggestion and whether it was accepted'
const browser = await chromium.launch({ channel: 'msedge', headless: true })
for (const [width, height] of [[1280, 800], [375, 812]]) {
  const page = await browser.newPage({ viewport: { width, height } })
  // Stubbed, so no real model call is made. Only the fonts leave the machine.
  await page.route('**/api/suggest', (route) =>
    route.fulfill({
      json: {
        rewrite: 'We will log all suggestions and whether it was accepted',
        rationale: 'Replaced "are going to" with "will" and tightened the wording, keeping what gets logged.',
      },
    }),
  )
  await page.goto('http://127.0.0.1:5198/')
  await page.waitForSelector('.tiptap', { state: 'attached' })
  await page.evaluate(() => document.fonts.ready)
  await page.waitForTimeout(400)
  await page.evaluate((t) => {
    const w = document.createTreeWalker(document.querySelector('.tiptap'), NodeFilter.SHOW_TEXT)
    for (let n = w.nextNode(); n; n = w.nextNode()) {
      const i = n.textContent.indexOf(t)
      if (i >= 0) { const r = document.createRange(); r.setStart(n, i); r.setEnd(n, i + t.length); const s = getSelection(); s.removeAllRanges(); s.addRange(r); return }
    }
  }, SENTENCE)
  await page.waitForTimeout(200)
  await page.getByRole('toolbar').getByRole('button', { name: 'Shorter', exact: true }).click()
  await page.getByRole('button', { name: 'Accept all' }).waitFor()
  await page.waitForTimeout(250)
  await page.screenshot({ path: `${OUT}/review-${width}.png` })
  await page.close()
}
await Promise.race([browser.close(), new Promise((r) => setTimeout(r, 3000))])
process.exit(0)

