        const last = touching.at(-1)
        if (first !== undefined && last !== undefined && first !== last) {
          mergeRange(drafts, first, last)
          return true
        }
      }
      return false
    }

    merged = mergeTouching(originalSpans, 'original') || mergeTouching(rewriteSpans, 'rewrite')
  }
