import { APP_NAME } from '../shared/appName.ts'
import type { SuggestErrorCode, SuggestRequest, Suggestion } from '../shared/contract.ts'
import { parseModelOutput } from './parseModelOutput.ts'
import { buildUserMessage, SUGGESTION_SCHEMA, SYSTEM_PROMPT } from './prompt.ts'

const OPENROUTER_URL = 'https://openrouter.ai/api/v1/chat/completions'
const REQUEST_TIMEOUT_MS = 45_000
const MAX_OUTPUT_TOKENS = 4000

export interface ModelUsage {
  promptTokens: number | null
  completionTokens: number | null
  reasoningTokens: number | null
  costUsd: number | null
}

export type ModelResult =
  | { ok: true; suggestion: Suggestion; usage: ModelUsage }
  | { ok: false; code: SuggestErrorCode; message: string; detail: string }

export interface ModelCallOptions {
  apiKey: string
  model: string
  fetchFn?: typeof fetch
  signal?: AbortSignal
}

interface CompletionResponse {
  choices?: { message?: { content?: string | null } }[]
  usage?: {
    prompt_tokens?: number
    completion_tokens?: number
    completion_tokens_details?: { reasoning_tokens?: number }
    cost?: number
  }
}

/**
 * One request, one call. A failure is returned, never retried: the user decides
 * whether to spend another call.
 */
export async function callModel(
  request: SuggestRequest,
  { apiKey, model, fetchFn = fetch, signal }: ModelCallOptions,
): Promise<ModelResult> {
  const timeout = AbortSignal.timeout(REQUEST_TIMEOUT_MS)

  let response: Response
  try {
    response = await fetchFn(OPENROUTER_URL, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
        'X-Title': APP_NAME,
      },
      body: JSON.stringify({
        model,
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user', content: buildUserMessage(request) },
        ],
        response_format: {
          type: 'json_schema',
          json_schema: { name: 'suggestion', strict: true, schema: SUGGESTION_SCHEMA },
        },
        // Skip providers that would silently ignore the schema.
        provider: { require_parameters: true },
        max_tokens: MAX_OUTPUT_TOKENS,
      }),
      signal: signal ? AbortSignal.any([signal, timeout]) : timeout,
    })
  } catch (error) {
    return {
      ok: false,
      code: 'upstream_error',
      message: "Couldn't reach the model. Check your connection and try again.",
      detail: error instanceof Error ? error.name : 'unknown network error',
    }
  }

  if (await isBudgetFailure(response)) {
    return {
      ok: false,
      code: 'budget_exhausted',
      message: 'The credit on this API key has run out. Your document is unchanged.',
      detail: `OpenRouter returned ${response.status}: no credit left`,
    }
  }

  if (!response.ok) {
    return {
      ok: false,
      code: 'upstream_error',
      message: messageForStatus(response.status),
      detail: `OpenRouter returned ${response.status}`,
    }
  }

  let body: CompletionResponse
  try {
    body = (await response.json()) as CompletionResponse
  } catch {
    return invalidOutput('response body was not JSON')
  }

  const parsed = parseModelOutput(body.choices?.[0]?.message?.content ?? '')
  if (!parsed.ok) return invalidOutput(parsed.reason)

  return {
    ok: true,
    suggestion: parsed.suggestion,
    usage: {
      promptTokens: body.usage?.prompt_tokens ?? null,
      completionTokens: body.usage?.completion_tokens ?? null,
      reasoningTokens: body.usage?.completion_tokens_details?.reasoning_tokens ?? null,
      costUsd: body.usage?.cost ?? null,
    },
  }
}

/**
 * OpenRouter reports no credit as a 402, and a key over its own spending cap as
 * a 403 mentioning the limit. The body is only inspected, never passed on.
 */
async function isBudgetFailure(response: Response): Promise<boolean> {
  if (response.status === 402) return true
  if (response.status !== 403) return false
  const body = await response.clone().text().catch(() => '')
  return /limit|credit/i.test(body)
}

function invalidOutput(detail: string): ModelResult {
  return {
    ok: false,
    code: 'invalid_model_output',
    message: "The model's reply couldn't be read. Your document is unchanged. Try again.",
    detail,
  }
}

function messageForStatus(status: number): string {
  if (status === 401 || status === 403) {
    return 'The OpenRouter API key was rejected. Check the key in your .env file.'
  }
  if (status === 429) return 'The model is rate limited right now. Wait a moment and try again.'
  return 'The model service had a problem. Try again.'
}

import { serve } from '@hono/node-server'
import { createApp } from './app.ts'

/** Chosen by the comparison logged in NOTES.md. */
const MODEL = 'anthropic/claude-sonnet-5.5'

const PORT = 8787
/** Local only, so nobody else on the network can spend the key's credit. */
const HOSTNAME = '127.0.0.1'

const apiKey = process.env.OPENROUTER_API_KEY ?? ''
if (apiKey === '') {
  console.warn('[server] OPENROUTER_API_KEY is not set. Suggestions will show an error until it is.')
}

serve({ fetch: createApp({ apiKey, model: MODEL }).fetch, port: PORT, hostname: HOSTNAME }, () => {
  console.log(`[server] listening on http://${HOSTNAME}:${PORT}`)
})

import { Hono } from 'hono'
import {
  MAX_CONTEXT_CHARS,
  MAX_INSTRUCTION_CHARS,
  MAX_SELECTION_CHARS,
  SUGGEST_PATH,
} from '../shared/contract.ts'
import type {
  SuggestContext,
  SuggestErrorBody,
  SuggestErrorCode,
  SuggestRequest,
} from '../shared/contract.ts'
import { callModel } from './openRouter.ts'

export interface AppOptions {
  apiKey: string
  model: string
  fetchFn?: typeof fetch
}

const HTTP_STATUS = {
  bad_request: 400,
  missing_api_key: 500,
  budget_exhausted: 402,
  upstream_error: 502,
  invalid_model_output: 502,
} as const satisfies Record<SuggestErrorCode, number>

function errorBody(code: SuggestErrorCode, message: string): SuggestErrorBody {
  return { error: { code, message } }
}

export function createApp({ apiKey, model, fetchFn }: AppOptions) {
  const app = new Hono()

  app.post(SUGGEST_PATH, async (c) => {
    if (apiKey === '') {
      return c.json(
        errorBody('missing_api_key', 'No API key found. Add OPENROUTER_API_KEY to your .env file and restart.'),
        HTTP_STATUS.missing_api_key,
      )
    }

    const request = parseSuggestRequest(await c.req.json().catch(() => null))
    if (request === null) {
      return c.json(
        errorBody('bad_request', "That request couldn't be sent. Try a shorter selection."),
        HTTP_STATUS.bad_request,
      )
    }

    const result = await callModel(request, { apiKey, model, fetchFn, signal: c.req.raw.signal })
    if (!result.ok) {
      // The detail is written by us and never includes request headers.
      console.error(`[suggest] ${result.code}: ${result.detail}`)
      return c.json(errorBody(result.code, result.message), HTTP_STATUS[result.code])
    }

    return c.json(result.suggestion)
  })

  return app
}

function isBoundedString(value: unknown, max: number): value is string {
  return typeof value === 'string' && value.length <= max
}

function parseContextField(value: unknown): string | null | undefined {
  if (value === null) return null
  return isBoundedString(value, MAX_CONTEXT_CHARS) ? value : undefined
}

function parseContext(value: unknown): SuggestContext | null | undefined {
  if (value === null) return null
  if (typeof value !== 'object') return undefined

  const { heading, before, after } = value as Record<string, unknown>
  const parsed = {
    heading: parseContextField(heading),
    before: parseContextField(before),
    after: parseContextField(after),
  }
  if (parsed.heading === undefined || parsed.before === undefined || parsed.after === undefined) {
    return undefined
  }
  return { heading: parsed.heading, before: parsed.before, after: parsed.after }
}

/** Returns null for anything that doesn't match the contract. */
export function parseSuggestRequest(body: unknown): SuggestRequest | null {
  if (typeof body !== 'object' || body === null) return null

  const { selection, target, instruction, currentSuggestion, context } = body as Record<string, unknown>
  if (!isBoundedString(selection, MAX_SELECTION_CHARS) || selection.trim() === '') return null
  if (target !== 'selection' && target !== 'section') return null
  if (!isBoundedString(instruction, MAX_INSTRUCTION_CHARS) || instruction.trim() === '') return null

  // A rewrite can legitimately be longer than the selection it replaces.
  const suggestion = currentSuggestion ?? null
  if (suggestion !== null && !isBoundedString(suggestion, MAX_SELECTION_CHARS * 2)) return null

  const parsedContext = parseContext(context ?? null)
  if (parsedContext === undefined) return null

  return { selection, target, instruction, currentSuggestion: suggestion, context: parsedContext }
}

