2	import type { SuggestErrorCode, SuggestRequest, Suggestion } from '../shared/contract.ts'
3	import { parseModelOutput } from './parseModelOutput.ts'
4	import { buildUserMessage, SUGGESTION_SCHEMA, SYSTEM_PROMPT } from './prompt.ts'
5	
6	const OPENROUTER_URL = 'https://openrouter.ai/api/v1/chat/completions'
7	const REQUEST_TIMEOUT_MS = 45_000
8	const MAX_OUTPUT_TOKENS = 4000
9	
10	export interface ModelUsage {
11	  promptTokens: number | null
12	  completionTokens: number | null
13	  reasoningTokens: number | null
14	  costUsd: number | null
15	}
16	
17	export type ModelResult =
18	  | { ok: true; suggestion: Suggestion; usage: ModelUsage }
19	  | { ok: false; code: SuggestErrorCode; message: string; detail: string }
20	
21	export interface ModelCallOptions {
22	  apiKey: string
23	  model: string
24	  fetchFn?: typeof fetch
25	  signal?: AbortSignal
26	}
27	
28	interface CompletionResponse {
29	  choices?: { message?: { content?: string | null } }[]
30	  usage?: {
31	    prompt_tokens?: number
32	    completion_tokens?: number
33	    completion_tokens_details?: { reasoning_tokens?: number }
34	    cost?: number
35	  }
36	}
37	
38	/**
39	 * One request, one call. A failure is returned, never retried: the user decides
40	 * whether to spend another call.
41	 */
42	export async function callModel(
43	  request: SuggestRequest,
44	  { apiKey, model, fetchFn = fetch, signal }: ModelCallOptions,
45	): Promise<ModelResult> {
46	  const timeout = AbortSignal.timeout(REQUEST_TIMEOUT_MS)
47	
48	  let response: Response
49	  try {
50	    response = await fetchFn(OPENROUTER_URL, {
51	      method: 'POST',
52	      headers: {
53	        Authorization: `Bearer ${apiKey}`,
54	        'Content-Type': 'application/json',
55	        'X-Title': APP_NAME,
56	      },
57	      body: JSON.stringify({
58	        model,
59	        messages: [
60	          { role: 'system', content: SYSTEM_PROMPT },
61	          { role: 'user', content: buildUserMessage(request) },
62	        ],
63	        response_format: {
64	          type: 'json_schema',
65	          json_schema: { name: 'suggestion', strict: true, schema: SUGGESTION_SCHEMA },
66	        },
67	        // Skip providers that would silently ignore the schema.
68	        provider: { require_parameters: true },
69	        max_tokens: MAX_OUTPUT_TOKENS,
70	      }),
71	      signal: signal ? AbortSignal.any([signal, timeout]) : timeout,
72	    })
73	  } catch (error) {
74	    return {
75	      ok: false,
76	      code: 'upstream_error',
77	      message: "Couldn't reach the model. Check your connection and try again.",
78	      detail: error instanceof Error ? error.name : 'unknown network error',
79	    }
80	  }
81	
82	  if (await isBudgetFailure(response)) {
83	    return {
84	      ok: false,
85	      code: 'budget_exhausted',
86	      message: 'The credit on this API key has run out. Your document is unchanged.',
87	      detail: `OpenRouter returned ${response.status}: no credit left`,
88	    }
89	  }
90	
91	  if (!response.ok) {
92	    return {
93	      ok: false,
94	      code: 'upstream_error',
95	      message: messageForStatus(response.status),
96	      detail: `OpenRouter returned ${response.status}`,
97	    }
98	  }
99	
100	  let body: CompletionResponse
101	  try {
102	    body = (await response.json()) as CompletionResponse
103	  } catch {
104	    return invalidOutput('response body was not JSON')
105	  }
106	
107	  const parsed = parseModelOutput(body.choices?.[0]?.message?.content ?? '')
108	  if (!parsed.ok) return invalidOutput(parsed.reason)
109	
110	  return {
111	    ok: true,
112	    suggestion: parsed.suggestion,
113	    usage: {
114	      promptTokens: body.usage?.prompt_tokens ?? null,
115	      completionTokens: body.usage?.completion_tokens ?? null,
116	      reasoningTokens: body.usage?.completion_tokens_details?.reasoning_tokens ?? null,
117	      costUsd: body.usage?.cost ?? null,
118	    },
119	  }
120	}
121	
122	/**
123	 * OpenRouter reports no credit as a 402, and a key over its own spending cap as
124	 * a 403 mentioning the limit. The body is only inspected, never passed on.
125	 */
126	async function isBudgetFailure(response: Response): Promise<boolean> {
127	  if (response.status === 402) return true
128	  if (response.status !== 403) return false
129	  const body = await response.clone().text().catch(() => '')
130	  return /limit|credit/i.test(body)
131	}
132	
133	function invalidOutput(detail: string): ModelResult {
134	  return {
135	    ok: false,
136	    code: 'invalid_model_output',
137	    message: "The model's reply couldn't be read. Your document is unchanged. Try again.",
138	    detail,
139	  }
140	}
141	
142	function messageForStatus(status: number): string {
143	  if (status === 401 || status === 403) {
144	    return 'The OpenRouter API key was rejected. Check the key in your .env file.'
145	  }
146	  if (status === 429) return 'The model is rate limited right now. Wait a moment and try again.'
147	  return 'The model service had a problem. Try again.'
148	}
