// Recomputes the audit's contrast ratios from the current token values.
const hex = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16))
const over = (fg, alpha, bg) => fg.map((c, i) => c * alpha + bg[i] * (1 - alpha))
const mix = (a, b, t) => a.map((c, i) => c + (b[i] - c) * t)
const lum = (rgb) => {
  const [r, g, b] = rgb.map((c) => {
    const s = c / 255
    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4
  })
  return 0.2126 * r + 0.7152 * g + 0.0722 * b
}
const ratio = (a, b) => {
  const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x)
  return ((hi + 0.05) / (lo + 0.05)).toFixed(2)
}
const white = [255, 255, 255]
const app = hex('#f5f3f0')
const navy = hex('#0f223a')
const navyLight = hex('#2f466f')
// linear-gradient(navy 40%, navy-light 160%): the far corner (100%) is half way.
const lightestNavy = mix(navy, navyLight, (100 - 40) / (160 - 40))
const ink = hex('#0f223a')
const sky = hex('#9ab3eb')
const backdropDark = over([15, 34, 58], 0.97, navy)
const backdropLight = over([47, 70, 111], 0.97, white)

const rows = [
  ['muted on app background', ratio(hex('#5f6672'), app), '5.22'],
  ['muted (section numbers) on white', ratio(hex('#5f6672'), white), '5.78'],
  ['mockup gutter #a8a39a on white', ratio(hex('#a8a39a'), white), '2.51'],
  ['white 0.7 (deleted text) on lightest navy', ratio(over(white, 0.7, lightestNavy), lightestNavy), '5.61'],
  ['mockup deleted #8e8a7c on lightest navy', ratio(hex('#8e8a7c'), lightestNavy), '2.73'],
  ['palette idle 0.42, darkest backdrop', ratio(over(white, 0.42, backdropDark), backdropDark), '3.94'],
  ['palette idle 0.42, lightest backdrop', ratio(over(white, 0.42, backdropLight), backdropLight), '3.07'],
  ['mockup palette idle 0.28, lightest backdrop', ratio(over(white, 0.28, backdropLight), backdropLight), '2.50'],
  ['white 0.82 (card body) on lightest navy', ratio(over(white, 0.82, lightestNavy), lightestNavy), '8.92'],
  ['white 0.6 (placeholder) on lightest navy', ratio(over(white, 0.6, lightestNavy), lightestNavy), '4.81'],
  ['ink on sky (Apply)', ratio(ink, sky), '7.65'],
]
for (const [name, now, claimed] of rows) console.log(`${now === claimed ? 'same' : 'DIFF'}  ${now} (notes ${claimed})  ${name}`)

