'fetch outside src/api:'
Get-ChildItem -Recurse src -Include *.ts,*.tsx | Where-Object { $_.FullName -notmatch '\\src\\api\\' -and $_.Name -notmatch '\.test\.' } | Select-String -Pattern '\bfetch\(' | ForEach-Object { "  $($_.Path):$($_.LineNumber)" }
'state hooks in components:'
Get-ChildItem -Recurse src/components -Include *.tsx | Select-String -Pattern '\b(useState|useReducer|useEffect|useRef)\b' | ForEach-Object { "  $($_.Path.Replace((Get-Location).Path + '\', '')):$($_.LineNumber): $($_.Line.Trim())" }
'VITE_ variables:'
Get-ChildItem -Recurse src,server,shared,vite.config.ts -Include *.ts,*.tsx | Select-String -Pattern 'VITE_' | ForEach-Object { "  $($_.Path):$($_.LineNumber)" }
'dist contains key name or key prefix:'
Get-ChildItem -Recurse dist -File | Select-String -Pattern 'OPENROUTER_API_KEY|sk-or-' -List | ForEach-Object { "  $($_.Path)" }
'done'

