// Lists every "quoted" string in NOTES.md's spec rows and proof columns that no test file contains.
import { readFileSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'

const root = process.argv[2]
const files = []
const walk = (dir) => {
  for (const name of readdirSync(dir)) {
    const path = join(dir, name)
    if (statSync(path).isDirectory()) walk(path)
    else if (/\.(test|spec)\.tsx?$/.test(name)) files.push(path)
  }
}
for (const dir of ['src', 'server', 'e2e']) walk(join(root, dir))
const tests = files.map((file) => readFileSync(file, 'utf8')).join('\n')

const notes = readFileSync(join(root, 'NOTES.md'), 'utf8')
const proofs = notes
  .split('\n')
  .filter((line) => line.startsWith('|'))
  .map((line) => line.split('|').slice(-3, -2)[0] ?? '') // the Proof column only
const quoted = new Set(proofs.flatMap((cell) => [...cell.matchAll(/"([^"]+)"/g)].map((m) => m[1])))

let missing = 0
for (const name of quoted) {
  if (!tests.includes(name)) {
    missing += 1
    console.log(`NOT FOUND: ${name}`)
  }
}
console.log(`${quoted.size} quoted names checked, ${missing} not found`)

